import WebCamImage from "../WebCamImage/WebCamImage";

import {ID_MODAL_WEBCAM} from "../../../shared/config/config";

function ModalWebCam({photoWidth, handlePhotoLoad}: {
    photoWidth: number,
    handlePhotoLoad: (event: any) => void
}) {
    return (
        <div className="modal fade bg-dark bg-opacity-25" id={ID_MODAL_WEBCAM} aria-hidden="true">
            <div className="modal-dialog modal-dialog-centered">
                <div className="modal-content">
                    <div className="modal-header border-bottom">
                        <h4 className="modal-title">Зарузка фото</h4>
                        <button type="button" className="btn-close" data-bs-dismiss="modal" aria-hidden="true"></button>
                    </div>
                    <div className="modal-body p-4 d-flex">
                        <WebCamImage photoWidth={photoWidth}/>
                    </div>
                    <div className="modal-footer d-flex justify-content-end">
                        <button type="button" className="btn btn-secondary" data-bs-dismiss="modal">Отмена</button>
                        <button type="button" className="btn btn-primary w-auto" data-bs-dismiss="modal"
                                onClick={handlePhotoLoad}>Загрузить
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}

export default ModalWebCam;