import {Dispatch, SetStateAction, useEffect, useState} from "react";
import {NavigateFunction, useNavigate} from "react-router-dom";

import {apiHandler} from "../../../shared/utils/ApiHandler";

import ReceiverVideo from "../../components/Receiver/ReceiverVideo";
import {cctvVideo} from "../../components/CCTV/CCTVVideo";

import PageTitle from "../../components/PageTitle/PageTitle";
import TableSensors from "../../components/TableSensors/TableSensors";
import levelDoubleClickHandler from "../../../shared/utils/levelDoubleClickHandler";
import getItemValue from "../../../shared/utils/getItemValue";
import upFirstLetter from "../../../shared/utils/upFirstLetter";
import ItemDetector from "../../components/ItemDetector/ItemDetector";
import VideoLoader from "../../components/VideoLoader/VideoLoader";

import camera from "../../../assets/images/icons/skud-and-video/camera.svg";

import {MkdItemType} from "../../../shared/types/mkd-items.type";
import {NameValueType} from "../../../shared/types/name-value.type";
import {SensorElementItemType} from "../../../shared/types/sensor-element-item.type";
import {VideoElementItemType} from "../../../shared/types/video-element-item.type";

import "./MkdPage.scss";

interface Props {
    mkdItems: MkdItemType[];
    mkdItemCurrent: MkdItemType;
    levels: NameValueType[];
    sensorItems: SensorElementItemType[];
    videoItems: VideoElementItemType[];
    setLevelsMkd: Dispatch<SetStateAction<NameValueType[]>>;
    setSensorItems: Dispatch<SetStateAction<SensorElementItemType[]>>;
    setVideoItems: Dispatch<SetStateAction<VideoElementItemType[]>>;
    setLoading: Dispatch<SetStateAction<boolean>>;
}

function MkdPage({mkdItems, mkdItemCurrent, levels, sensorItems, videoItems, setLevelsMkd, setSensorItems, setVideoItems, setLoading}: Props) {
    const navigate: NavigateFunction = useNavigate();

    const [cctvItems, setCctvItems] = useState<ReceiverVideo[]>([]);
    const [loadingItems, setLoadingItems] = useState<string[]>([]);

    function handleLevelDoubleClick(event: any): void {
        levelDoubleClickHandler(event, mkdItems, navigate);
    }

    useEffect(() => {
        if (mkdItemCurrent) {
            const idMkd = mkdItemCurrent.id;

            apiHandler.getMkdSensorItems({setLoading, idMkd, setSensorItems});
            apiHandler.getMkdVideoItems({setLoading, idMkd, setVideoItems});
            apiHandler.getMkdLevels({idMkd, setLevelsMkd});
        }
    }, [mkdItemCurrent]);

    useEffect(() => {
        const newLoadingItems: string[] = [];

        videoItems.forEach((video: VideoElementItemType) => {
            newLoadingItems.push(video.id);

            cctvVideo.showVideo(
                video,
                cctvItems,
                setCctvItems,
                loadingItems,
                setLoadingItems
            );
        });

        setLoadingItems(newLoadingItems);
    }, [videoItems]);

    useEffect(() => {
        console.log(sensorItems);
    }, [sensorItems]);

    useEffect(() => {
        videoItems.forEach((video: VideoElementItemType) => {
            const videoElement: HTMLElement | null = document.getElementById(`video-${video.id}`);

            if (videoElement) {
                if (!(videoElement as HTMLMediaElement).srcObject) {
                    video.isLoading = true;
                } else {
                    video.isLoading = false;
                }
            }
        });

    }, [videoItems, loadingItems]);

    return (
        <div className="mkd-page">
            <PageTitle title={`г.Москва, ${mkdItemCurrent && mkdItemCurrent.address}`}/>

            <div className="mkd-page__content">
                <div className="mkd-page__info">
                    <div className="mkd-page__levels">
                        {mkdItemCurrent.levels && mkdItemCurrent.levels.length > 0 &&
                            mkdItemCurrent.levels.map((level: string, index: number) => (
                                <div key={index}>
                                    <div className={`mkd-page__level mkd-page__level_${getItemValue(level, levels)} 
                                        ${mkdItemCurrent && mkdItemCurrent.incident && mkdItemCurrent.incidentLevels?.includes(level)                                    
                                            && "mkd-page__level_incident"}`}
                                         id={`level-${getItemValue(level, levels)}`}
                                         onDoubleClick={handleLevelDoubleClick}>
                                        <div
                                            className={`mkd-page__sensor-items mkd-page__sensor-items_${getItemValue(level, levels)}`}>
                                            {sensorItems && sensorItems.length > 0 &&
                                                Array.from(new Map([...sensorItems.filter(item => item.danger), ...sensorItems]
                                                    .filter((item: SensorElementItemType) => item.level === level)
                                                    .map((item: {
                                                        [key: string]: any
                                                    }) => [item["name"], item])).values())
                                                    .map((item: { [key: string]: any }, index: number) => {
                                                        return <ItemDetector key={index}
                                                                             item={item as SensorElementItemType}
                                                                             position="relative"/>
                                                    })
                                            }
                                        </div>
                                    </div>
                                    {videoItems && videoItems.length > 0 && mkdItemCurrent.levels && mkdItemCurrent.levels.length > 0 &&
                                        <div
                                            className={`mkd-page__camera mkd-page__camera_${getItemValue(level, levels)}`}>
                                            <img src={camera} alt="Камера"/>
                                        </div>
                                    }
                                </div>
                            ))}
                    </div>
                    <div className="mkd-page__video-items">
                        {mkdItemCurrent.levels && mkdItemCurrent.levels.map((level: string, index: number) => (
                            <div key={index}
                                 className={`mkd-page__video mkd-page__video_${getItemValue(level, levels)}`}>
                                <div className="mkd-page__video-title">Камеры ({upFirstLetter(level)})</div>
                                <div className="mkd-page__video-streams">
                                    {videoItems.filter((item: VideoElementItemType) => item.level === getItemValue(level, levels))
                                        .map((video: VideoElementItemType, index: number) => (
                                            <div key={index} className="video">
                                                {video && video.isLoading && <VideoLoader/>}
                                                <video
                                                    className={`video-stream ${video.danger ? "video-stream_danger" : ""}`}
                                                    id={`video-${video.id}`} muted autoPlay
                                                    playsInline></video>
                                            </div>
                                        ))}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="mkd-page__table">
                    <TableSensors sensorItems={sensorItems}/>
                </div>
            </div>
        </div>
    );
}

export default MkdPage;