import {InputHTMLAttributes, useEffect, useState} from "react";

import {DEBOUNCE} from "../../../shared/config/config";

interface Props {
    value: string | number;
    onChange: (value: string | number) => void;
    isLoading: boolean;
    debounce?: number;
}

function InputDebounced({ value: initialValue, onChange, isLoading, debounce = DEBOUNCE, ...props
                        }: Props & Omit<InputHTMLAttributes<HTMLInputElement>, 'onChange'>) {

    const [value, setValue] = useState(initialValue);

    useEffect(() => {
        setValue(initialValue);
    }, [initialValue]);

    useEffect(() => {
        const timeout = setTimeout(() => {
            onChange(value)
        }, debounce);

        return () => clearTimeout(timeout);
    }, [value])

    return (
        <input {...props} type="text" value={value} disabled={isLoading} onChange={e => setValue(e.target.value)}/>
    )
}

export default InputDebounced;