import {Dispatch, SetStateAction, useEffect, useState} from "react";

import Modal from 'bootstrap/js/dist/modal';

import {apiHandler} from "../../../shared/utils/ApiHandler";
import {modalActions} from "../../../shared/utils/ModalActions";

import {ID_MODAL_USER} from "../../../shared/config/config";

import InputDebounced from "../../components/InputDebounced/InputDebounced";
import TableUsers from "../../components/TableUsers/TableUsers";
import ModalUser from "../../components/ModalUser/ModalUser";

import {UserInfoType} from "../../../shared/types/user-info.type";

import "./Users.scss";
import SpinnerCustom from "../../components/SpinnerCustom/SpinnerCustom";

function Users({isLoading, setLoading, handleAlertOpen}: {
    isLoading: boolean,
    setLoading: Dispatch<SetStateAction<boolean>>,
    handleAlertOpen: (type: "success" | "fail", text: string) => void
}) {
    const [usersList, setUsersList] = useState<UserInfoType[]>([]);
    const [userId, setUserId] = useState<string>("");
    const [userAction, setUserAction] = useState<"add" | "edit" | "delete">("add");
    const [globalFilter, setGlobalFilter] = useState<string>('');
    const [modal, setModal] = useState<Modal | null>(null);
    const [isUserModalActive, setUserModalActive] = useState<boolean>(false);

    function handleAddButtonClick(): void {
        setUserAction('add');
        setUserModalActive(true);
    }

    function handleUserModalClose(isDataChanged: boolean): void {
        modalActions.closeModal(modal);
        setUserModalActive(false);

        if (isDataChanged) {
            apiHandler.getUsersAll({setLoading, setUsersList});
        } else {
            userAction === "delete" && apiHandler.getUsersAll({setLoading, setUsersList});
        }
    }

    useEffect(() => {
        apiHandler.getUsersAll({setLoading, setUsersList});
    }, []);

    useEffect(() => {
        if (isUserModalActive) {
            modalActions.openModal(ID_MODAL_USER, setModal);
        }
    }, [isUserModalActive]);

    useEffect((): void => {
        if (userAction === "add") {
            setUserId("");
        }
    }, [userAction]);

    return (
        <div className="users" id="users">
            <div className="d-flex align-items-center justify-content-between">
                <div className="d-flex align-items-center gap-5">
                    <div className={`text-start h6 m-0`}>
                        Сотрудники
                    </div>
                    <button type="button"
                            className="btn btn-outline-primary py-1 px-3"
                            style={{height: "32px"}}
                            disabled={isLoading}
                            onClick={handleAddButtonClick}>
                        Добавить
                    </button>
                </div>
                <InputDebounced
                    value={globalFilter ?? ''}
                    onChange={value => setGlobalFilter(String(value))}
                    isLoading={isLoading}
                    className="form-control invalid users__search"
                    placeholder="Поиск"
                    id="searchInput"
                />
            </div>
            {isLoading
                ? <SpinnerCustom/>
                : usersList.length > 0 &&
                <TableUsers users={usersList}
                            setUserId={setUserId}
                            setUserAction={setUserAction}
                            globalFilter={globalFilter}
                            setGlobalFilter={setGlobalFilter}
                            setUserModalActive={setUserModalActive}/>
            }

            {isUserModalActive &&
                <ModalUser userId={userId}
                           userAction={userAction}
                           setUserAction={setUserAction}
                           onClose={handleUserModalClose}
                           handleAlertOpen={handleAlertOpen}
                           isLoading={isLoading}
                           setLoading={setLoading}
                />
            }
        </div>
    );
}

export default Users;