    postRequestService({setRequestLoading, requestServiceItem, handleAlertOpen}: {
        setRequestLoading: Dispatch<SetStateAction<boolean>>,
        requestServiceItem: RequestServiceType,
        handleAlertOpen: (type: "success" | "fail", text: string) => void
    }) {
        if (this.isDevMode) {
            console.log(requestServiceItem)
            setRequestLoading(true);

            setTimeout(() => {
                setRequestLoading(false);

                const submitButton: HTMLElement | null = document.getElementById("service-submit-button");
                if (submitButton) {
                    submitButton.innerText = SUCCESS_SERVICE_POST_MESSAGE;
                    submitButton.setAttribute("disabled", "true");
                }
                handleAlertOpen("success", SUCCESS_SERVICE_POST_MESSAGE);
            }, 2000);
        } else {
            console.log(requestServiceItem)
            setRequestLoading(true);

            api.postRequestServiceApi(requestServiceItem)
                .then((res: AxiosResponse): void => {
                    const response: ResponseDefaultType = res.data;
                    let error = null;

                    if (!(response as ResponseDefaultType).success) {
                        error = (response as ResponseDefaultType).message;
                    } else {
                        // чтобы успела подгрузиться картинка
                        setTimeout(() => {
                            handleAlertOpen("success", SUCCESS_SERVICE_POST_MESSAGE);
                        }, 100);

                        const submitButton: HTMLElement | null = document.getElementById("service-submit-button");
                        if (submitButton) {
                            submitButton.innerText = SUCCESS_SERVICE_POST_MESSAGE;
                            submitButton.setAttribute("disabled", "true");
                        }
                    }

                    if (error) {
                        handleAlertOpen("fail", error);
                        throw new Error(error);
                    }
                })
                .catch((error) => {
                    console.error(ERROR_DATA_PROCESS, error.message);
                    handleAlertOpen("fail", ERROR_DATA_SEND);
                })
                .finally(() => {
                    setRequestLoading(false);
                });
        }
    }

