    getAccessQqCode({accessId, setAccessQqCode, setQrCodeError}: {
        accessId: string,
        setAccessQqCode: Dispatch<SetStateAction<string>>,
        setQrCodeError: Dispatch<SetStateAction<string | null>>,
    }) {
        // убрать, когда заработает бэк
        if (this.isDevMode && accessId !== "") {
            setAccessQqCode(qrCode);
            // setQrCodeError(ERROR_QR);
        } else {
            api.getAccessQqCodeApi(accessId)
                .then((response: Response) => {
                    if (!response.ok) {
                        throw new Error(`HTTP error! status: ${response.status}`);
                    }

                    // Проверяем Content-Type заголовок
                    const contentType = response.headers.get('content-type');
                    if (contentType && contentType.includes('application/json')) {
                        // Если ответ в формате JSON
                        return response.json().then((data: any) => {
                            if (data.success === false) {
                                setQrCodeError(ERROR_QR);
                                throw new Error(data.message || 'Ошибка сервера');
                            }
                            // Если JSON содержит URL изображения или другие данные
                            console.warn('Сервер вернул JSON, но ожидалось изображение:', data);
                            return null; // или обработайте JSON данные по необходимости
                        });
                    } else {
                        // Если ответ бинарный (изображение)
                        return response.blob();
                    }
                })
                .then((data: Blob | null) => {
                    if (data instanceof Blob) {
                        // Если данные — это Blob (изображение)
                        const objectURL: string = URL.createObjectURL(data);
                        setAccessQqCode(objectURL); // Устанавливаем URL изображения
                    } else {
                        // Если данные — это JSON (или null)
                        console.warn('Ожидалось изображение, но сервер вернул JSON.');
                        // Можно установить заглушку или обработать ошибку
                        setQrCodeError(ERROR_QR);
                        setAccessQqCode(''); // или setAccessQqCode(defaultImageUrl);
                    }
                })
                .catch((error) => {
                    console.error('Ошибка обработки данных:', error.message);
                    setQrCodeError(ERROR_QR);
                    setAccessQqCode(''); // Очищаем состояние или устанавливаем заглушку
                });
        }
    }

