    getUser({userId, setUserLoading, setUserAction, setUserData, setInitialUserData, handleAlertOpen}: {
        userId: string,
        setUserLoading: Dispatch<SetStateAction<boolean>>,
        setUserAction: Dispatch<SetStateAction<"add" | "edit" | "delete">>,
        setUserData: Dispatch<SetStateAction<UserInfoType>>,
        setInitialUserData: Dispatch<SetStateAction<UserInfoType>>,
        handleAlertOpen: (type: "success" | "fail", text: string) => void
    }) {
        // убрать, когда заработает бэк
        if (this.isDevMode) {
            const userCurrent: UserInfoType | undefined = usersListResponseTemp.find((user: UserInfoType) => user.id === userId);

            userCurrent && setUserData(userCurrent);
            userCurrent && setInitialUserData(userCurrent);
            setUserAction("edit");
            setUserLoading(false);
        } else {
            setUserLoading(true);

            api.getUserApi(userId)
                .then((res: AxiosResponse): void => {
                    const response: ResponseDefaultType | UserInfoType = res.data;
                    let error = null;

                    if (!(response as ResponseDefaultType).success) {
                        error = (response as ResponseDefaultType).message;
                    }

                    const successResponse: UserInfoType = response as UserInfoType;
                    if (!successResponse) {
                        error = ERROR_SERVER;
                    }

                    if (error) {
                        handleAlertOpen("fail", error);
                        throw new Error(error);
                    }

                    setUserData(successResponse);
                    setInitialUserData(successResponse);
                })
                .catch((error) => {
                    console.error(ERROR_DATA_PROCESS, error.message);
                    handleAlertOpen("fail", ERROR_SERVER);
                })
                .finally(() => {
                    setUserLoading(false);
                });
        }
    }

