import {Table} from "@tanstack/react-table";

function highlightSearchValue(table: Table<any>, item: string, display?: string) {
    const searchValue = table.getState().globalFilter.toLowerCase();

    return (
        <p key={item} className={`mb-0 ${display === "inline" ? "d-inline" : ""}`}>
            {item.substring(0, item.toString().toLowerCase().indexOf(searchValue))}
            <span
                className={`${searchValue !== "" && item.toString().toLowerCase().includes(searchValue) ? "bg-success bg-opacity-25" : ""}`}>
                   {item.substring(item.toString().toLowerCase().indexOf(searchValue), item.toString().toLowerCase().indexOf(searchValue) + searchValue.length)}
                </span>
            {item.substring(item.toString().toLowerCase().indexOf(searchValue) + searchValue.length)}
        </p>
    );
}

export default highlightSearchValue;