import {Dispatch, SetStateAction, useEffect, useMemo, useState} from "react";

import {
    ColumnDef,
    flexRender,
    getCoreRowModel,
    getFilteredRowModel,
    getPaginationRowModel,
    Table,
    useReactTable
} from "@tanstack/react-table";

import PaginationCustom from "../PaginationCustom/PaginationCustom";

import highlightSearchValue from "../../../shared/utils/highlightSearchValue";
import upFirstLetter from "../../../shared/utils/upFirstLetter";
import getUsersIdAccess from "../../../shared/utils/getUsersIdAccess";

import {UserInfoType} from "../../../shared/types/user-info.type";

import "./TableUsers.scss";

function TableUsers({users, setUserId, setUserAction, globalFilter, setGlobalFilter, setUserModalActive}: {
    users: UserInfoType[],
    setUserId: Dispatch<SetStateAction<string>>,
    setUserAction: Dispatch<SetStateAction<"add" | "edit" | "delete">>,
    globalFilter: string,
    setGlobalFilter: Dispatch<SetStateAction<string>>,
    setUserModalActive: Dispatch<SetStateAction<boolean>>,
}) {
    const [data, setData] = useState<UserInfoType[]>([]);
    const [paginationItems, setPaginationItems] = useState<HTMLTableRowElement[]>([]);

    useEffect(() => {
        setData(users);
    }, [users]);

    const columns: ColumnDef<UserInfoType, any>[] = useMemo<ColumnDef<UserInfoType, any>[]>(
        () => [
            {
                accessorKey: 'id',
                header: 'ID',
                filterFn: 'includesString',
                enableResizing: false,
                cell: ({getValue}) => getValue() && highlightSearchValue(table, getValue().toString()),
            },
            {
                accessorKey: 'fio',
                header: 'ФИО',
                filterFn: 'includesString',
                enableResizing: false,
                cell: ({getValue}) => getValue() && highlightSearchValue(table, getValue().toString()),
            },
            {
                accessorKey: 'uids',
                header: "Пропуска",
                filterFn: 'includesString',
                enableResizing: false,
                cell: ({getValue}) => getValue() && getValue().length > 0 &&
                    getUsersIdAccess(getValue()).map((card: string) => highlightSearchValue(table, card))
            },
            {
                accessorKey: 'org',
                header: 'Организация',
                filterFn: 'includesString',
                enableResizing: false,
                cell: ({getValue}) => getValue() && highlightSearchValue(table, upFirstLetter(getValue().toString())),
            },
            {
                accessorKey: 'position',
                header: 'Должность',
                enableResizing: false,
                filterFn: 'equalsString',
                cell: ({getValue}) => getValue() && highlightSearchValue(table, upFirstLetter(getValue().toString())),
            },
            {
                accessorKey: 'note',
                header: "Примечание",
                filterFn: 'includesString',
                enableResizing: false,
                cell: ({getValue}) => getValue() && highlightSearchValue(table, upFirstLetter(getValue().toString())),
            }
        ], []
    );

    const table: Table<UserInfoType> = useReactTable({
        data,
        columns,
        state: {
            globalFilter,
        },
        getCoreRowModel: getCoreRowModel(),
        getPaginationRowModel: getPaginationRowModel(),
        getFilteredRowModel: getFilteredRowModel(),
        onGlobalFilterChange: setGlobalFilter,
        getColumnCanGlobalFilter: () => {
            return true;
        },
        debugTable: false,
    });

    useEffect(() => {
        const tableElement: HTMLElement | null = document.getElementById("table-users");
        if (tableElement) {
            const itemsElements: HTMLTableRowElement[] = Array.from(tableElement.getElementsByTagName('tr')).slice(1);
            setPaginationItems(itemsElements);
        }
    }, [data]);

    return (
        <div className="table-users">
            <div className="table-responsive">
                {data.length > 0 && table.getRowModel().rows.length > 0 &&
                    <table className="table table-striped table-bordered mb-0 table-users__table" id="table-users">
                        <thead>
                        {table.getHeaderGroups().map(headerGroup => (
                            <tr key={headerGroup.id}>
                                {headerGroup.headers.map(header => (
                                    <th key={header.id}
                                        className={`p-3 ${header.id === "fio" ? "fio" : ""}`}>
                                        {header.isPlaceholder
                                            ? null
                                            : flexRender(
                                                header.column.columnDef.header,
                                                header.getContext()
                                            )}
                                    </th>
                                ))}
                            </tr>
                        ))}
                        </thead>
                        <tbody>
                        {table.getRowModel().rows.map(row => (
                            <tr key={row.id} {...{
                                style: {cursor: 'pointer'}
                            }}
                                onDoubleClick={function test() {
                                    if (!row.getIsGrouped()) {
                                        setUserId(row.original.id);
                                        setUserAction("edit");
                                        setUserModalActive(true);
                                    }
                                }}
                                title='Двойной клик для редактирования'>
                                {row.getVisibleCells().map(cell => (
                                    <td key={cell.id}
                                        className={`p-3 ${cell.column.id === "fio" ? "fio" : ""}`}>
                                        {flexRender(cell.column.columnDef.cell, cell.getContext())}
                                    </td>
                                ))}
                            </tr>
                        ))}
                        </tbody>
                    </table>
                }

                {paginationItems && paginationItems.length > 10 &&
                    <PaginationCustom paginationItems={paginationItems} type="full" itemsPerPageInitial={10}/>
                }

            </div>
        </div>

    );
}

export default TableUsers;