import {BASE_URL} from "../config/config";
import {axiosInstance} from "../../app/App";
import {RequestServiceType} from "../types/request-service.type";
import {RequestAccessType} from "../types/request-access.type";
import {UserInfoType} from "../types/user-info.type";

class Api {
    readonly baseUrl: string;

    constructor() {
        this.baseUrl = BASE_URL;
    }

    //Проверка ответа от сервера
    _checkResponse(res: Response) {
        if (res.ok) {
            return res.json();
        }
        // если ошибка, отклоняем промис
        return Promise.reject(res);
    }

    async signupApi(login: string, password: string) {
        const res: Response = await fetch(`${this.baseUrl}/signup`, {
            method: "POST",
            headers: {
                Accept: "application/json",
                "Content-Type": "application/json",
            },
            body: JSON.stringify({login, password})
        });
        return this._checkResponse(res);
    }

    async loginApi(login: string, password: string) {
        const res: Response = await fetch(`${this.baseUrl}/login`, {
            method: "POST",
            headers: {
                Accept: "application/json",
                "Content-Type": "application/json",
                "Access-Control-Allow-Origin": "*"
            },
            body: JSON.stringify({login, password})
        });
        return this._checkResponse(res);
    }

    async logoutApi() {
        return await axiosInstance.get(`${this.baseUrl}/logout`);
    }

    async getAddressesApi() {
        const res: Response = await fetch(`${this.baseUrl}/address?filter=all`, {
            headers: {
                Accept: "application/json",
                "Content-Type": "application/json",
                'Access-Control-Allow-Origin': '*',
            },
        });
        return this._checkResponse(res);

        // return await axiosInstance.get(`${this.baseUrl}/address?filter=all`);
    }

    async getIncidentsApi() {
        return await axiosInstance.get(`${this.baseUrl}/incident?filter=all`);
    }

    async readIncidentApi(incidentId: string) {
        return await axiosInstance.put(`${this.baseUrl}/incident?id=${incidentId}&isRead=true`);
    }

    async readAllIncidentsApi() {
        return await axiosInstance.put(`${this.baseUrl}/incident?filter=all&isRead=true`);
    }

    async getMkdLevelsApi(idMkd: string) {
        return await axiosInstance.get(`${this.baseUrl}/level?idMkd=${idMkd}`);
    }

    async getSensorsAllApi() {
        return await axiosInstance.get(`${this.baseUrl}/sensor?filter=all`);
    }

    async getMkdSensorItemsApi(idMkd: string) {
        return await axiosInstance.get(`${this.baseUrl}/sensor?filter=mkd&idMkd=${idMkd}`);
    }

    async getLevelSensorItemsApi(idMkd: string, level: string) {
        return await axiosInstance.get(`${this.baseUrl}/sensor?filter=level&idMkd=${idMkd}&level=${level}`);
    }

    async getMkdVideoItemsApi(idMkd: string) {
        return await axiosInstance.get(`${this.baseUrl}/video?filter=mkd&idMkd=${idMkd}`);
    }

    async getLevelVideoItemsApi(idMkd: string, level: string) {
        return await axiosInstance.get(`${this.baseUrl}/video?filter=level&idMkd=${idMkd}&level=${level}`);
    }

    async postRequestServiceApi(requestServiceItem: RequestServiceType) {
        return await axiosInstance.post(`${this.baseUrl}/serviceRequest`,
            JSON.stringify({
                id: "",
                org: requestServiceItem.org,
                fio: requestServiceItem.fio,
                system: requestServiceItem.system,
                comment: requestServiceItem.comment
            })
        );
    }

    async getRequestAccessItemsApi() {
        return await axiosInstance.get(`${this.baseUrl}/accessRequest?filter=all`);
    }

    async postRequestAccessApi(requestAccessItem: RequestAccessType) {
        return await axiosInstance.post(`${this.baseUrl}/accessRequest`,
            JSON.stringify({
                id: "",
                comment: requestAccessItem.comment,
                dateAccessFrom: requestAccessItem.dateAccessFrom,
                dateAccessTo: requestAccessItem.dateAccessTo,
                dateCreation: requestAccessItem.dateCreation,
                fio: requestAccessItem.fio,
                org: requestAccessItem.org,
                phone: requestAccessItem.phone,
                position: requestAccessItem.position,
                status: "в работе",
                target: requestAccessItem.target,
            })
        );
    }

    async putRequestAccessApi(requestAccessItem: RequestAccessType) {
        return await axiosInstance.put(`${this.baseUrl}/accessRequest?id=${requestAccessItem.id}`,
            JSON.stringify({
                id: requestAccessItem.id,
                comment: requestAccessItem.comment,
                dateAccessFrom: requestAccessItem.dateAccessFrom,
                dateAccessTo: requestAccessItem.dateAccessTo,
                dateCreation: requestAccessItem.dateCreation,
                fio: requestAccessItem.fio,
                org: requestAccessItem.org,
                phone: requestAccessItem.phone,
                position: requestAccessItem.position,
                status: requestAccessItem.status,
                target: requestAccessItem.target,
            })
        );
    }

    async getRequestAccessDataApi() {
        return await axiosInstance.get(`${this.baseUrl}/accessRequest?filter=data`);
    }

    async getAccessQqCodeApi(accessId: string) {
        // return await axiosInstance.get(`${this.baseUrl}/qrcode?accessId=${accessId}`,{responseType: 'blob'});
        return await fetch(`${this.baseUrl}/qrcode?accessId=${accessId}`);

    }

    async uploadFileApi(dataName: string, dateFrom: string, dateTo: string) {
        return await fetch(`${this.baseUrl}/download?filter=${dataName}&dateFrom=${dateFrom}&dateTo=${dateTo}`);
    }

    async getUsersAllApi() {
        return await axiosInstance.get(`${this.baseUrl}/user?filter=all`);
    }

    async getUserApi(id: string) {
        return await axiosInstance.get(`${this.baseUrl}/user?id=${id}`);
    }

    async addUserApi(userData: UserInfoType) {
        return await axiosInstance.post(`${this.baseUrl}/user`,
            JSON.stringify({
                id: "",
                fio: userData.fio,
                uids: [],
                org: userData.org,
                position: userData.position,
                phone: userData.phone,
                note: userData.note,
                photoUrl: "",
            })
        );
    }

    async editUserApi(userData: UserInfoType) {
        return await axiosInstance.put(`${this.baseUrl}/user?id=${userData.id}`,
            JSON.stringify({
                id: userData.id,
                fio: userData.fio,
                uids: userData.uids,
                org: userData.org,
                position: userData.position,
                phone: userData.phone,
                note: userData.note,
                photoUrl: userData.photoUrl,
            })
        );
    }

    async deleteUserApi(id: string) {
        return await axiosInstance.delete(`${this.baseUrl}/user?id=${id}`);
    }

    async getOrgsAllApi() {
        return await axiosInstance.get(`${this.baseUrl}/org?filter=all`);
    }

    async getTargetsAllApi() {
        return await axiosInstance.get(`${this.baseUrl}/target?filter=all`);
    }

}

export const api: Api = new Api();