import {useEffect, useState} from "react";

import PaginationCustom from "../PaginationCustom/PaginationCustom";
import upFirstLetter from "../../../shared/utils/upFirstLetter";

import {SensorElementItemType} from "../../../shared/types/sensor-element-item.type";

import "./TableSensors.scss";

function TableSensors({sensorItems}: { sensorItems: SensorElementItemType[] }) {
    const [items, setItems] = useState<HTMLTableRowElement[]>([]);

    const titles: string[] = ["Датчик", "Этаж", "Статус", "Значение"];

    useEffect(() => {
        const tableElement: HTMLElement | null = document.getElementById("table-sensors");
        if (tableElement) {
            const itemsElements: HTMLTableRowElement[] = Array.from(tableElement.getElementsByTagName('tr')).slice(1);
            setItems(itemsElements);
        }
    }, [sensorItems]);

    return (
        <>
            <table className="table table-striped table-bordered mb-0 table-skud w-100" id="table-sensors">
                <thead>
                <tr>
                    {titles.map((title: string, index: number) => (
                        <th key={index} className="table-sensors__th p-3">{title}</th>
                    ))}
                </tr>
                </thead>
                <tbody>
                {sensorItems && sensorItems.length > 0 &&
                    sensorItems.map((item: SensorElementItemType, index: number) => (
                        <tr key={index}
                            className={`table-sensors__tr table-sensors__tr_${item.id} d-none
                                ${item.danger ? "table-sensors__tr_incident" : ""}`}
                            id={`table-sensor-tr-${item.id}`}>
                            <td className="p-3">{upFirstLetter(item.name)}</td>
                            <td className="p-3">{upFirstLetter(item.level)}</td>
                            <td className="p-3">{upFirstLetter(item.status)}</td>
                            <td className="p-3">{item.value ? item.value : "Нет"}</td>
                        </tr>
                    ))}
                </tbody>
            </table>

            {sensorItems &&
                <PaginationCustom paginationItems={items} type="full" itemsPerPageInitial={10}/> }
        </>
    );
}

export default TableSensors;