import upFirstLetter from "../../../shared/utils/upFirstLetter";

import {VideoElementItemType} from "../../../shared/types/video-element-item.type";
import {SensorElementItemType} from "../../../shared/types/sensor-element-item.type";

import './ItemDetector.scss';

function ItemDetector({item, position}: { item: VideoElementItemType | SensorElementItemType, position: string}) {
    return (
        <div className="item-detector"
             id={item.id}
             style={{top: position === "absolute" ? `${item.top}px` : "",
                 left: position === "absolute" ? `${item.left}px` : "",
                 position: position === "absolute" ? "absolute" : "relative"}}>
            <button type="button"
                    className={`item-detector__icon ${item.danger ? "item-detector__icon_danger" : ""} 
                    item-detector__icon_${item.id.includes("cam") ? "cam" : item.id.split("-")[0]}`}
                    style={{transform: `${position === "absolute" && "rotate" in item && `rotate(${item.rotate}deg)`}`}}>
            </button>

            {position === "absolute" && item && item.id.split("-")[0] !== "vk" &&
                <div id={`item-text-${item.id}`}
                    className={`item-detector__text ${item.danger ? "item-detector__text_danger" : ""} item-detector__text_${item.id.split("-")[1]}`}>
                    {upFirstLetter(item.name)}
                </div>
            }
        </div>
    );
}

export default ItemDetector;