import {Dispatch, SetStateAction, useEffect, useState} from "react";

import AccordionAddress from "../AccordionAddress/AccordionAddress";

import {MkdItemsType, MkdItemType} from "../../../shared/types/mkd-items.type";
import {NameValueType} from "../../../shared/types/name-value.type";

import './AsideLeft.scss';

interface Props {
    mkdItems: MkdItemType[];
    setMkdItemCurrent: Dispatch<SetStateAction<MkdItemType>>;
    addresses: MkdItemsType[];
    levels: NameValueType[];
}

function AsideLeft({mkdItems, setMkdItemCurrent, addresses, levels}: Props) {
    const [searchedAddresses, setSearchedAddresses] = useState<MkdItemsType[]>(addresses);

    function handleSearchChange(event: any) {
        const regEx = /[^А-Яа-я\d/]/;
        const filteredAddresses: MkdItemsType[] = addresses.map((address: MkdItemsType) => {
            const filteredMkdItems: MkdItemType[] = address.mkdItems.filter((item: MkdItemType) =>
                item.name.toLowerCase().replace(regEx, '').includes(event.target.value.toLowerCase().replace(regEx, ''))
            );
            return {org: address.org, mkdItems: filteredMkdItems}
        });
        setSearchedAddresses(filteredAddresses);
    }

    useEffect(() => {
        setSearchedAddresses(addresses);
    }, [addresses]);

    return (
        <div className="aside-left">
            <div className="aside-left__search">
                <input type="text"
                       className="aside-left__input w-100 form-control"
                       placeholder="Поиск по адресу"
                       onChange={handleSearchChange}/>
            </div>
            <AccordionAddress mkdItems={mkdItems}
                              setMkdItemCurrent={setMkdItemCurrent}
                              levels={levels}
                              searchedAddresses={searchedAddresses}/>
        </div>
    );
}

export default AsideLeft;