import {Dispatch, SetStateAction, useState} from "react";
import {NavigateFunction} from "react-router-dom";

import FormAuth from "../../components/FormAuth/FormAuth";

import {apiHandler} from "../../../shared/utils/ApiHandler";

import {AccountType} from "../../../shared/types/account.type";

import './Auth.scss';

function Auth({isLoading, setLoading, setLoggedIn, setAccountInfo, handleAlertOpen, navigate}: {
    isLoading: boolean,
    setLoading: Dispatch<SetStateAction<boolean>>,
    setLoggedIn: Dispatch<SetStateAction<boolean>>,
    setAccountInfo: Dispatch<SetStateAction<AccountType>>,
    handleAlertOpen: (type: "success" | "fail", text: string) => void,
    navigate: NavigateFunction
}) {
    const [formType, setFormType] = useState<"signup" | "login">("login");

    function handleAuth(login: string, password: string): void {
        formType === "login"
            ? apiHandler.login({
                login, password, setLoading, setLoggedIn, setAccountInfo, handleAlertOpen, navigate
            })
            : apiHandler.signup({
                login, password, setLoading, setLoggedIn, setAccountInfo, handleAlertOpen, navigate
            });
    }

    return (
        <div className="auth" id="auth">
            <FormAuth formType={formType} setFormType={setFormType} isLoading={isLoading} onSubmit={handleAuth}/>
        </div>
    );
}

export default Auth;