import {useEffect, useState} from "react";

import {
    regexOnlyNumbers
} from "../../../shared/config/regex";

import upFirstLetter from "../../../shared/utils/upFirstLetter";

import {UidType, UserInfoType} from "../../../shared/types/user-info.type";

import "../../../assets/styles/bootstrap-variables.scss";

function FormUserData({userData, setterUserDataTemp}: {
    userData: UserInfoType,
    setterUserDataTemp: ({name, value}: { [key: string]: string }) => void
}) {
    const [accessPass, setAccessPass] = useState<boolean>(false);

    const onDataChange = (event: any): void => {
        event.target.value
            ? event.target.classList.add("form-item_filled")
            : event.target.classList.remove("form-item_filled");

        const value = (event.target as HTMLInputElement).value;
        if (event.target.name === "phone") {
            event.target.value = value.length < 3 ? "+7" : "+" + value.replace(regexOnlyNumbers, "");
        }

        setterUserDataTemp({name: event.target.name, value: event.target.value});
    }

    useEffect(() => {
        const userAccessPass: UidType | undefined = userData.uids.find(uid => uid.idAccess === "");
        setAccessPass(!!userAccessPass);
    }, [userData]);

    return (
        <div className="d-flex flex-column p-3 border rounded gap-3 h-100">

            {/*{userAction !== "add" &&*/}
            {/*    <input name="id"*/}
            {/*           type="text"*/}
            {/*           className="form-control form-item_shadow"*/}
            {/*           defaultValue={userData.id}*/}
            {/*           disabled/>*/}
            {/*}*/}

            <input name="fio"
                   type="text"
                   className="form-control form-item_shadow"
                   defaultValue={userData.fio}
                   placeholder="ФИО"
                   autoComplete="off"
                   onChange={onDataChange}/>

            <input name="org"
                   type="text"
                   className="form-control form-item_shadow"
                   defaultValue={upFirstLetter(userData.org)}
                   placeholder="Организация"
                   autoComplete="off"
                   onChange={onDataChange}/>

            <input name="position"
                   type="text"
                   className="form-control form-item_shadow"
                   defaultValue={upFirstLetter(userData.position)}
                   placeholder="Должность"
                   autoComplete="off"
                   onChange={onDataChange}/>

            <input name="phone"
                   type="text"
                   className="form-control form-item_shadow"
                   placeholder="Телефон представителя"
                   defaultValue={userData.phone}
                   autoComplete="off"
                   maxLength={12}
                   onFocus={(event) => {
                       const value = (event.target as HTMLInputElement).value;
                       (event.target as HTMLInputElement).value = value === "" ? "+7" : value;
                   }}
                   onBlur={(event) => {
                       const value = (event.target as HTMLInputElement).value;
                       (event.target as HTMLInputElement).value = value.length < 3 ? "" : value;
                   }}
                   onChange={onDataChange}/>

            <textarea name="comment"
                      placeholder="Примечание"
                      className="form-control form-item_shadow form-item__comment"
                      onChange={onDataChange}>
            </textarea>

            {/*{!accessPass &&*/}
            {/*    <div className="form-check">*/}
            {/*        <input className="form-check-input" type="checkbox" value="" id="createPass" name="createPass"/>*/}
            {/*        <label className="form-check-label" htmlFor="createPass">*/}
            {/*            Сгенерировать постоянный пропуск*/}
            {/*        </label>*/}
            {/*    </div>*/}
            {/*}*/}
        </div>
    );
}

export default FormUserData;