import {apiHandler} from "../../../shared/utils/ApiHandler";

import "./ButtonUpload.scss";

function ButtonUpload({tableName}: { tableName: "request" | "history" }) {
    function handleUpload() {
        const dataName = tableName === "request" ? "accessRequest" : "incident";
        const dateFrom = "";
        const dateTo = "";

        apiHandler.uploadFile({dataName, dateFrom, dateTo});
    }

    return (
        <div className="button-upload w-100">
            <button type="button" className="btn btn-outline-primary mb-4" id="upload-button" onClick={handleUpload}>
                Выгрузить статистику за период
            </button>
        </div>
    )
}

export default ButtonUpload;