import {useEffect, useState} from "react";

import FormUserData from "../FormUserData/FormUserData";
import FormUserUids from "../FormUserUids/FormUserUids";
import FormUserPhoto from "../FormUserPhoto/FormUserPhoto";
import QrCode from "../QrCode/QrCode";

import imageUrlToBase64 from "../../../shared/utils/imageUrlToBase64";

import {UidType, UserInfoType} from "../../../shared/types/user-info.type";

interface Props {
    userAction: "add" | "edit" | "delete";
    userData: UserInfoType;
    initialUserData: UserInfoType;
    setterUserDataTemp: ({name, value}: { [key: string]: string }) => void;
    handleAlertOpen: (type: "success" | "fail", text: string) => void;
    handleDeleteUser: (event: any) => void;
    submit: (event: any) => void;
    deleteUser: () => void;
    isUserDataChanged: boolean;
}

const FormUser = (props: Props) => {
    const [isQr, setQr] = useState<boolean>(false);
    const [uidUrl, setUidUrl] = useState<string>("");
    const [uidName, setUidName] = useState<string>("");

    useEffect(() => {
        if (props.userAction === "edit") {
            const accessPass: UidType | undefined = props.userData.uids.find((uid: UidType) => uid.idAccess === "");
            if (accessPass && accessPass.qrUrl !== "") {
                imageUrlToBase64(accessPass.qrUrl).then((data: any) => setUidUrl(data));
                setUidName(accessPass.idAccess);
                setQr(true);
            } else {
                setUidUrl("");
                setUidName("");
                setQr(false);
            }
        }
    }, [props.userData]);

    return (
        <>
            <form id="form-user">
                <div className="d-flex justify-content-around gap-2">
                    <div className="d-flex flex-column justify-content-between align-items-center gap-1">
                        <FormUserPhoto {...props}/>
                        {props.userAction !== "add" &&
                            <FormUserUids uidName={uidName}
                                          setUidUrl={setUidUrl}
                                          setUidName={setUidName}
                                          setQr={setQr}
                                          {...props}/>
                        }
                    </div>
                    <div className={`mt-0 px-0 ${isQr ? "col-6" : "col-9"}`}
                         style={{height: "330px"}}>
                        <FormUserData {...props}/>
                    </div>
                    {isQr &&
                        <div className="w-100">
                            <QrCode accessQrCode={uidUrl} accessId={uidName} handleAlertOpen={props.handleAlertOpen}/>
                        </div>
                    }
                </div>

                <div className={`d-flex mt-4
                        ${props.userAction !== "add" ? "justify-content-between" : "justify-content-end"}`}>
                    {props.userAction !== "add" &&
                        <div className="p-0">
                            <button type="button" className="btn btn-sm btn-danger"
                                    onClick={props.handleDeleteUser}>
                                Удалить
                            </button>
                        </div>
                    }
                    <div className="p-0">
                        <button type="button"
                                className="btn btn-sm btn-primary"
                                onClick={props.submit}
                                disabled={!props.isUserDataChanged}>
                            {props.userAction === "edit" ? "Сохранить" : "Добавить"}
                        </button>
                    </div>
                </div>
            </form>
        </>
    );
}

export default FormUser;