import {Dispatch, SetStateAction} from "react";
import ReceiverVideo from "../Receiver/ReceiverVideo";
import {VideoElementItemType} from "../../../shared/types/video-element-item.type";

class CCTVVideo {
    private cctv: ReceiverVideo | null = null;

    showVideo(video: VideoElementItemType,
              cctvItems: ReceiverVideo[],
              setCctvItems: Dispatch<SetStateAction<ReceiverVideo[]>>,
              loadingItems: string[],
              setLoadingItems: Dispatch<SetStateAction<string[]>>
    ): void {
            this.cctv = new ReceiverVideo(video, loadingItems, setLoadingItems);
            setCctvItems([this.cctv, ...cctvItems]);
        }

}

export const cctvVideo: CCTVVideo = new CCTVVideo();