import PageTitle from "../../components/PageTitle/PageTitle";
import TableBasic from "../../components/TableBasic/TableBasic";

import upFirstLetter from "../../../shared/utils/upFirstLetter";

import {MkdItemType} from "../../../shared/types/mkd-items.type";
import {IncidentItemType} from "../../../shared/types/incident-Item.type";
import {NameValueType} from "../../../shared/types/name-value.type";

import "./History.scss";

function History({mkdItems, incidents, levelsAll, requestAccessStatuses}: {
    mkdItems: MkdItemType[],
    incidents: IncidentItemType[],
    levelsAll: string[],
    requestAccessStatuses: NameValueType[]
}) {
    const titles: string[] = ["Здание", "Точка установки", "Датчик", "Статус", "Значение", "Аварийное событие", "Дата и время"];

    const addresses: string[] = Array.from(new Set(getTableItems().map(item => item.address)))
        .filter(item => item !== "");
    const levels: string[] = levelsAll;
    const names: string[] = Array.from(new Set(getTableItems().map(item => upFirstLetter(item.name)))).sort();
    const statuses: string[] = Array.from(new Set(getTableItems().map(item => upFirstLetter(item.status)))).sort();
    const values: string[] = Array.from(new Set(getTableItems().map(item => item.value)))
        .filter(item => item !== null).sort();
    const dangers: boolean[] = [true, false];

    const filterItems: { [key: string]: any }[] = [
        {title: "Адрес", name: "address", value: addresses},
        {title: "Точка установки", name: "level", value: levels},
        {title: "Датчик", name: "name", value: names},
        {title: "Статус", name: "statusSensor", value: statuses},
        {title: "Значение", name: "value", value: values},
        {title: "Событие", name: "danger", value: dangers},
    ];

    function getTableItems(): { [key: string]: any }[] {
        return incidents.map((incident: IncidentItemType) => {
            const address: string | undefined = mkdItems.find((item: MkdItemType) => item.id === incident.idMkd)?.address;

            return {
                address: address ? address : "Адрес не найден",
                level: incident.level,
                name: incident.name,
                status: incident.status,
                value: incident.value,
                danger: incident.danger,
                date: incident.date,
            };
        });
    }

    return (
        <div className="history">
            <PageTitle title="Журнал событий"/>
            <div className="history__table">
                <TableBasic tableName="history"
                            items={getTableItems()}
                            filterItems={filterItems}
                            titles={titles}
                            requestAccessStatuses={requestAccessStatuses}/>
            </div>
        </div>
    );
}

export default History;