import {useEffect, useState} from "react";
import {Navigate, Route, Routes, useLocation, useNavigate} from "react-router-dom"

import axios, {AxiosResponse} from "axios";
import 'bootstrap';

import {api} from "../shared/utils/Api";
import {apiHandler} from "../shared/utils/ApiHandler";

import ReceiverWs from "./components/Receiver/ReceiverWs";

import ProtectedRoute from "./components/ProtectedRoute/ProtectedRoute";
import SpinnerCustom from "./components/SpinnerCustom/SpinnerCustom";
import Auth from "./pages/Auth/Auth";
import Header from "./layout/Header/Header";
import AsideLeft from "./components/AsideLeft/AsideLeft";
import Main from "./pages/Main/Main";
import MkdPage from "./pages/MkdPage/MkdPage";
import Floor from "./pages/Floor/Floor";
import RequestAccess from "./pages/RequestAccess/RequestAccess";
import RequestAccessList from "./pages/RequestAccessList/RequestAccessList";
import History from "./pages/History/History";
import Page404 from "./pages/Page404/Page404";
import AlertCustom from "./components/AlertCustom/AlertCustom";
import Report from "./pages/Report/Report";
import RequestService from "./pages/RequestService/RequestService";
import Users from "./pages/Users/Users";

import mergeMkdItemsFromAddresses from "../shared/utils/mergeMkdItemsFromAddresses";
import sortByMkd from "../shared/utils/sortByMkd";

import {
    IS_DEV_MODE,
    CREATION_LINK,
    FLOOR_LINK,
    HISTORY_LINK,
    EDIT_LINK,
    ACCESS_LIST_LINK,
    MKD_LINK,
    MONITORING_LINK,
    AUTH_LINK,
    PAGE_NOT_FOUND_LINK,
    KEY_LOGGED,
    KEY_ACCOUNT_INFO,
    KEY_CURRENT_MKD,
    KEY_CURRENT_LEVEL,
    BASE_URL,
    REPORT_LINK, SERVICE_LINK, KEY_CURRENT_REQUEST, IS_AUTH, USERS_LINK,
} from "../shared/config/config";

import {mkdItemDefault} from "../shared/config/default-items/mkd-item-default";
import {userDefault} from "../shared/config/default-items/user-default";

import {requestAccessItemDefault} from "../shared/config/default-items/request-access-item-default";
import {requestAccessStatusList} from "../shared/config/const-items/request-access-status-list";

import {UserInfoType} from "../shared/types/user-info.type";
import {MkdItemsType, MkdItemType} from "../shared/types/mkd-items.type";
import {RequestAccessType} from "../shared/types/request-access.type";
import {IncidentItemType,} from "../shared/types/incident-Item.type";
import {NameValueType} from "../shared/types/name-value.type";
import {SensorElementItemType} from "../shared/types/sensor-element-item.type";
import {VideoElementItemType} from "../shared/types/video-element-item.type";
import {WsSensorItemType} from "../shared/types/ws-sensor-item.type";
import {AccountType} from "../shared/types/account.type";
import {accountDefault} from "../shared/config/default-items/account-default";

export const axiosInstance = axios.create({
    baseURL: BASE_URL, // Replace with your API base URL
    headers: {
        'Content-Type': 'application/json;charset=UTF-8',
        Accept: "text/html,application/xhtml+xml,application/json",
        "Access-Control-Allow-Origin": "*"
    }
});

function App() {
    const location = useLocation();
    const pathName: string = location.pathname;
    const navigate = useNavigate();

    const [isLoading, setLoading] = useState<boolean>(false);
    const loggedInInit: string | null = localStorage.getItem(KEY_LOGGED);
    const [loggedIn, setLoggedIn]
        = useState<boolean>(loggedInInit ? JSON.parse(loggedInInit) : false);
    const accountInfoInit: string | null = localStorage.getItem(KEY_ACCOUNT_INFO);
    const [accountInfo, setAccountInfo]
        = useState<AccountType>(accountInfoInit ? JSON.parse(accountInfoInit) : accountDefault);
    const [addresses, setAddresses] = useState<MkdItemsType[]>([]);
    const [mkdItems, setMkdItems] = useState<MkdItemType[]>([]);
    const [incidents, setIncidents] = useState<IncidentItemType[]>([]);
    const mkdItemCurrentInit: string | null = localStorage.getItem(KEY_CURRENT_MKD);
    const [mkdItemCurrent, setMkdItemCurrent]
        = useState<MkdItemType>(mkdItemCurrentInit ? JSON.parse(mkdItemCurrentInit) : mkdItemDefault);
    const [currentIncidents, setCurrentIncidents] = useState<IncidentItemType[]>([]);
    const [sensorItems, setSensorItems] = useState<SensorElementItemType[]>([]);
    const [videoItems, setVideoItems] = useState<VideoElementItemType[]>([]);
    const [sensorLevelItems, setSensorLevelItems] = useState<SensorElementItemType[]>([]);
    const [videoLevelItems, setVideoLevelItems] = useState<VideoElementItemType[]>([]);
    const [levelsMkd, setLevelsMkd] = useState<NameValueType[]>([]);
    const [levelsAll, setLevelsAll] = useState<string[]>([]);
    const levelItemCurrentInit: string | null = localStorage.getItem(KEY_CURRENT_LEVEL);
    const [levelItemCurrent, setLevelItemCurrent]
        = useState<string>(levelItemCurrentInit ? JSON.parse(levelItemCurrentInit) : "");
    const [requestAccessList, setRequestAccessList]
        = useState<RequestAccessType[]>([]);
    const requestAccessCurrentInit: string | null = localStorage.getItem(KEY_CURRENT_REQUEST);
    const [requestAccessCurrent, setRequestAccessCurrent]
        = useState<RequestAccessType>(requestAccessCurrentInit ? JSON.parse(requestAccessCurrentInit) : requestAccessItemDefault);
    const [requestAccessStatuses, setRequestAccessStatuses] = useState<NameValueType[]>([]);
    const [isAlertOpen, setAlertOpen] = useState<boolean>(false);
    const [alertText, setAlertText] = useState<string>("");
    const [alertType, setAlertType] = useState<"success" | "fail">("success");
    const [wsItem, setWsItem] = useState<ReceiverWs | null>(null);
    const [incidentWs, setIncidentWs] = useState<IncidentItemType | null>(null);
    const [sensorWs, setSensorWs] = useState<WsSensorItemType | null>(null);

    function handleAlertOpen(type: "success" | "fail", text: string): void {
        setAlertText(text);
        setAlertType(type);
        setAlertOpen(true);

        const delay = type === "success" ? 2000 : 10000;

        setTimeout(() => {
            setAlertOpen(false);
        }, delay);
    }

    function doLogout(): void {
        localStorage.clear();
        setLoggedIn(false);
        setAccountInfo(accountDefault);
        navigate(AUTH_LINK);
    }

    function logout(): void {
        if (!IS_AUTH) {
            doLogout();
        } else {
            setLoading(true);

            api.logoutApi()
                .then((res: AxiosResponse<any, any>): void => {

                })
                .catch((error) => {
                    doLogout();
                })
                .finally(() => {
                    setLoading(false);
                });
        }
    }

    // // Add a request interceptor
    // axiosInstance.interceptors.request.use(
    //     function (config) {
    //         return config;
    //     },
    //     function (error) {
    //         console.error(error.response);
    //         return Promise.reject(error);
    //     }
    // );
    //
    // // Add a response interceptor
    // axiosInstance.interceptors.response.use(
    //     function (response) {
    //         console.log("Response: ", response.data);
    //         return response;
    //     },
    //     function (error) {
    //         // Handle the response error
    //         if (error.response) {
    //             console.error(error.response);
    //         }
    //
    //         // Handle unauthorized error
    //         if (error.response && error.response.status === 401) {
    //             console.error(ERROR_401);
    //             doLogout();
    //         }
    //         return Promise.reject(error);
    //     }
    // );

    useEffect(() => {
        if (!loggedIn) {
            doLogout();
        }
    }, [loggedIn]);

    useEffect(() => {
        if (!loggedIn) {
            navigate(AUTH_LINK);
        } else {
            pathName === "/sf" && navigate(MONITORING_LINK);
        }
    }, []);

    useEffect(() => {
        if (pathName === MONITORING_LINK || pathName === HISTORY_LINK || pathName === MKD_LINK || pathName === FLOOR_LINK) {
            apiHandler.getAddresses({setLoading, setAddresses});
            apiHandler.getIncidents({setIncidents});
        }

        if (pathName === ACCESS_LIST_LINK || pathName === CREATION_LINK || pathName === EDIT_LINK) {
            apiHandler.getRequestAccessItems({setLoading, setRequestAccessList});
        }

        if (pathName === CREATION_LINK || pathName === EDIT_LINK || pathName === ACCESS_LIST_LINK) {
            setRequestAccessStatuses(requestAccessStatusList);
        }

        if (!IS_DEV_MODE) {
            if (pathName === MONITORING_LINK || pathName === HISTORY_LINK || pathName === MKD_LINK || pathName === FLOOR_LINK) {
                if (wsItem === null) {
                    const wsItemNew: ReceiverWs = new ReceiverWs(setIncidentWs, setSensorWs);
                    setWsItem(wsItemNew);
                }
            } else {
                if (wsItem !== null) {
                    wsItem.close();
                    setWsItem(null);
                }
            }
        }
    }, [pathName]);

    useEffect(() => {
        if (incidentWs && !incidents.some((item: IncidentItemType) => JSON.stringify(item) === JSON.stringify(incidentWs))) {
            incidentWs && setIncidents([incidentWs, ...incidents])

            if (addresses && addresses.length > 0) {
                const currentMkd = mkdItems.find((mkdItem: MkdItemType) => mkdItem.id === incidentWs.idMkd);

                if (currentMkd) {
                    if (currentMkd.id === incidentWs.idMkd) {
                        currentMkd.incident = incidentWs.danger;

                        if (incidentWs.level) {
                            const levels: string[] = currentMkd.incidentLevels ? currentMkd.incidentLevels : [];
                            currentMkd.incidentLevels = [...levels, incidentWs.level]
                        }
                    }
                }

            }
        }
    }, [incidentWs]);

    useEffect(() => {
        if (sensorWs) {
            if (sensorItems && sensorItems.length > 0) {
                const currentSensor = sensorItems.find((item: SensorElementItemType) => item.id === sensorWs.id);
                if (currentSensor) {
                    currentSensor.status = sensorWs.status;
                    currentSensor.value = sensorWs.value;
                }
            }
            if (sensorLevelItems && sensorLevelItems.length > 0) {
                const currentLevelSensor = sensorLevelItems.find((item: SensorElementItemType) => item.id === sensorWs.id);
                if (currentLevelSensor) {
                    currentLevelSensor.status = sensorWs.status;
                    currentLevelSensor.value = sensorWs.value;
                }
            }
        }
    }, [sensorWs]);

    useEffect(() => {
        if (pathName === HISTORY_LINK && addresses && addresses.length > 0) {
            let levelsAll: string [] = [];
            addresses.forEach((address: MkdItemsType) => {
                address.mkdItems.forEach((item: MkdItemType) => {
                    item.levels.forEach((level: string) => {
                        !(levelsAll.includes(level)) && levelsAll.push(level);
                    });
                });
            });
            setLevelsAll(levelsAll);
        }

        addresses.forEach((address: MkdItemsType) => {
            address.mkdItems.forEach((item: MkdItemType) => {
                item.disabled = item.id !== "65";
            });
        });
    }, [addresses]);

    useEffect(() => {
        if (addresses && addresses.length > 0) {
            addresses.forEach((address: MkdItemsType) => {
                if (incidents && incidents.length > 0 && addresses && addresses.length > 0) {
                    incidents.forEach((incident: IncidentItemType) => {
                        address.mkdItems.forEach((mkdItem: MkdItemType) => {

                            if (mkdItem.id === incident.idMkd) {
                                mkdItem.incident = incident.danger;

                                if (incident.level) {
                                    const levels: string[] = mkdItem.incidentLevels ? mkdItem.incidentLevels : [];
                                    mkdItem.incidentLevels = [...levels, incident.level]
                                }
                            }
                        });
                    });
                }
            });
            setAddresses(addresses);
            setMkdItems(sortByMkd(mergeMkdItemsFromAddresses(addresses)));
        }

    }, [addresses, incidents]);


    useEffect(() => {
        mkdItemCurrentInit && setMkdItemCurrent(JSON.parse(mkdItemCurrentInit));
    }, [mkdItemCurrentInit]);

    useEffect(() => {
        levelItemCurrentInit && setLevelItemCurrent(JSON.parse(levelItemCurrentInit));
    }, [levelItemCurrentInit]);

    useEffect(() => {
        requestAccessCurrentInit && setRequestAccessCurrent(JSON.parse(requestAccessCurrentInit));
    }, [requestAccessCurrentInit]);

    useEffect(() => {
        incidents && mkdItemCurrent && mkdItemCurrent.id &&
        setCurrentIncidents(incidents.filter((incident: IncidentItemType) => incident.idMkd === mkdItemCurrent.id));

        incidents && sensorItems && incidents.forEach((incident: IncidentItemType) => {
            sensorItems.map((item: SensorElementItemType) => {
                if (incident.idSensor === item.id) return item.danger = incident.danger;
            });
        });

        incidents && sensorLevelItems && incidents.forEach((incident: IncidentItemType) => {
            sensorLevelItems.map((item: SensorElementItemType) => {
                if (incident.idSensor === item.id) return item.danger = incident.danger;
            });
        });
    }, [incidents, mkdItemCurrent?.id, levelItemCurrent, sensorItems, sensorLevelItems]);

    return (
        <>
            {loggedIn &&
                <Header accountInfo={accountInfo}
                        pathName={pathName}
                        onLogout={logout}
                />
            }

            {isLoading
                ? <SpinnerCustom/>
                : <div className={`${
                    pathName === MONITORING_LINK || pathName === AUTH_LINK || pathName === REPORT_LINK || pathName === SERVICE_LINK
                        ? "content"
                        : pathName === MKD_LINK || pathName === FLOOR_LINK
                            ? "content-wrapper"
                            : "content-wrapper flex-column"}`}>

                    {(pathName === MONITORING_LINK || pathName === MKD_LINK || pathName === FLOOR_LINK) &&
                        <AsideLeft mkdItems={mkdItems}
                                   setMkdItemCurrent={setMkdItemCurrent}
                                   addresses={addresses}
                                   levels={levelsMkd}/>
                    }

                    <Routes>
                        <Route path={AUTH_LINK}
                               element={
                                   <Auth isLoading={isLoading}
                                         setLoading={setLoading}
                                         setLoggedIn={setLoggedIn}
                                         setAccountInfo={setAccountInfo}
                                         handleAlertOpen={handleAlertOpen}
                                         navigate={navigate}
                                   />
                               }
                        />
                        <Route path={MONITORING_LINK}
                               element={
                                   <ProtectedRoute loggedIn={loggedIn}>
                                       <Main mkdItems={mkdItems}
                                             setMkdItemCurrent={setMkdItemCurrent}
                                             incidents={incidents}
                                             setIncidents={setIncidents}/>
                                   </ProtectedRoute>
                               }
                        />
                        <Route path={MKD_LINK}
                               element={
                                   <ProtectedRoute loggedIn={loggedIn}>
                                       <MkdPage mkdItems={mkdItems}
                                                mkdItemCurrent={mkdItemCurrent}
                                                levels={levelsMkd}
                                                sensorItems={sensorItems}
                                                videoItems={videoItems}
                                                setLevelsMkd={setLevelsMkd}
                                                setSensorItems={setSensorItems}
                                                setVideoItems={setVideoItems}
                                                setLoading={setLoading}/>
                                   </ProtectedRoute>
                               }
                        />
                        <Route path={FLOOR_LINK}
                               element={
                                   <ProtectedRoute loggedIn={loggedIn}>
                                       <Floor mkdItemCurrent={mkdItemCurrent}
                                              levelItemCurrent={levelItemCurrent}
                                              levels={levelsMkd}
                                              incidents={currentIncidents}
                                              sensorItems={sensorLevelItems}
                                              videoItems={videoLevelItems}
                                              setLevelsMkd={setLevelsMkd}
                                              setSensorLevelItems={setSensorLevelItems}
                                              setVideoLevelItems={setVideoLevelItems}
                                              setLoading={setLoading}/>
                                   </ProtectedRoute>
                               }
                        />

                        <Route path={HISTORY_LINK}
                               element={
                                   <ProtectedRoute loggedIn={loggedIn}>
                                       <History mkdItems={mkdItems}
                                                incidents={incidents}
                                                levelsAll={levelsAll}
                                                requestAccessStatuses={requestAccessStatuses}/>
                                   </ProtectedRoute>
                               }
                        />
                        <Route path={ACCESS_LIST_LINK}
                               element={
                                   <ProtectedRoute loggedIn={loggedIn}>
                                       <RequestAccessList setLoading={setLoading}
                                                          requestAccessList={requestAccessList}
                                                          setRequestAccessCurrent={setRequestAccessCurrent}
                                                          requestAccessStatuses={requestAccessStatuses}/>
                                   </ProtectedRoute>
                               }

                        />
                        <Route path={SERVICE_LINK}
                               element={
                                   <ProtectedRoute loggedIn={loggedIn}>
                                       <RequestService accountInfo={accountInfo} handleAlertOpen={handleAlertOpen}/>
                                   </ProtectedRoute>
                               }

                        />
                        <Route path={REPORT_LINK}
                               element={
                                   <ProtectedRoute loggedIn={loggedIn}>
                                       <Report/>
                                   </ProtectedRoute>
                               }

                        />
                        <Route path={USERS_LINK}
                               element={
                                   <ProtectedRoute loggedIn={loggedIn}>
                                       <Users isLoading={isLoading}
                                              setLoading={setLoading}
                                              handleAlertOpen={handleAlertOpen}/>
                                   </ProtectedRoute>
                               }

                        />

                        <Route path={CREATION_LINK}
                               element={
                                   <ProtectedRoute loggedIn={loggedIn}>
                                       <RequestAccess requestAccessCurrent={requestAccessItemDefault}
                                                      setRequestAccessCurrent={setRequestAccessCurrent}
                                                      requestAccessList={requestAccessList}
                                                      setRequestAccessList={setRequestAccessList}
                                                      requestAccessStatuses={requestAccessStatuses}
                                                      handleAlertOpen={handleAlertOpen}/>
                                   </ProtectedRoute>
                               }
                        />
                        <Route path={EDIT_LINK}
                               element={
                                   <ProtectedRoute loggedIn={loggedIn}>
                                       <RequestAccess requestAccessCurrent={requestAccessCurrent}
                                                      setRequestAccessCurrent={setRequestAccessCurrent}
                                                      requestAccessList={requestAccessList}
                                                      setRequestAccessList={setRequestAccessList}
                                                      requestAccessStatuses={requestAccessStatuses}
                                                      handleAlertOpen={handleAlertOpen}/>
                                   </ProtectedRoute>
                               }
                        />


                        <Route path={PAGE_NOT_FOUND_LINK}
                               element={
                                   <Page404/>
                               }
                        />
                        <Route path="*"
                               element={
                                   <Navigate replace to={PAGE_NOT_FOUND_LINK}/>
                               }
                        />
                        <Route path="/"
                               element={loggedIn
                                   ? <Navigate replace to={AUTH_LINK}/>
                                   : <Navigate replace to={MONITORING_LINK}/>
                               }
                        />
                    </Routes>

                    {isAlertOpen && <AlertCustom type={alertType} text={alertText}/>}
                </div>
            }
        </>
    );
}

export default App;
