import {Dispatch, SetStateAction} from "react";

import MediaMTXWebRTCReader from "../MediaMTXWebRTCReader/MediaMTXWebRTCReader";

import {BASE_VIDEO_URL} from "../../../shared/config/config";

import {VideoElementItemType} from "../../../shared/types/video-element-item.type";

class ReceiverVideo {
    readonly videoElement: VideoElementItemType;
    readonly loadingItems: string[];
    readonly setLoadingItems: Dispatch<SetStateAction<string[]>>;
    private media: MediaMTXWebRTCReader | null = null;

    constructor(
        video: VideoElementItemType,
        loadingItems: string[],
        setLoadingItems: Dispatch<SetStateAction<string[]>>
    ) {
        this.videoElement = video;
        this.loadingItems = loadingItems;
        this.setLoadingItems = setLoadingItems;
        this.setMedia();
    }

    setMedia() {
        this.media = new MediaMTXWebRTCReader({
            url: new URL("http://" + BASE_VIDEO_URL + "/" + this.videoElement.id + "/whep"),
            onError: (err: any) => {
                console.log("Error: " + err);
            },
            onTrack: (evt: any) => {
                console.log("onTrack");
            }
        }, this.videoElement, this.loadingItems, this.setLoadingItems);
    }

    onClose() {
        if (this.media) this.media.onClose();
    }

}

export default ReceiverVideo;