import {Dispatch, SetStateAction, useEffect, useState} from "react";
import {useLocation} from "react-router-dom";

import {apiHandler} from "../../../shared/utils/ApiHandler";

import PageTitle from "../../components/PageTitle/PageTitle";
import FormAccess from "../../components/FormAccess/FormAccess";
import SpinnerCustom from "../../components/SpinnerCustom/SpinnerCustom";

import {convertDateToString, convertStringToDate} from "../../../shared/utils/dateFormatActions";

import {requestAccessFieldNames} from "../../../shared/config/request-access-field-names";
import {
    CREATION_LINK,
    EDIT_LINK, ERROR_DATE_FROM_TO,
    ERROR_EMPTY_FIELDS,
    ERROR_PHONE,
    KEY_CURRENT_REQUEST
} from "../../../shared/config/config";

import {RequestAccessType, SetterRequestAccessItemType} from "../../../shared/types/request-access.type";
import {NameValueType} from "../../../shared/types/name-value.type";
import {RequestAccessDataType} from "../../../shared/types/request-access-data.type";

function RequestAccess({
                           requestAccessCurrent,
                           setRequestAccessCurrent,
                           requestAccessList,
                           setRequestAccessList,
                           requestAccessStatuses,
                           handleAlertOpen
                       }: {
    requestAccessCurrent: RequestAccessType,
    setRequestAccessCurrent: Dispatch<SetStateAction<RequestAccessType>>,
    requestAccessList: RequestAccessType[],
    setRequestAccessList: Dispatch<SetStateAction<RequestAccessType[]>>,
    requestAccessStatuses: NameValueType[],
    handleAlertOpen: (type: "success" | "fail", text: string) => void
}) {
    const location = useLocation();
    const pathName: string = location.pathname;

    const [action, setAction] = useState<"create" | "view" | "edit">("create");
    const [requestAccessItemTemp, setRequestAccessItemTemp] = useState<RequestAccessType>(requestAccessCurrent);
    const [isRequestLoading, setRequestLoading] = useState<boolean>(false);
    const [isRequestAccessPosted, setRequestAccessPosted] = useState<boolean>(false);
    const [requestAccessId, setRequestAccessId] = useState<string>(requestAccessCurrent.id);
    const [dataListItemsData, setDataListItemsData]
        = useState<RequestAccessDataType | null>(null);

    const setterRequestAccess = ({key, value}: SetterRequestAccessItemType): void => {
        setRequestAccessItemTemp({
            ...requestAccessItemTemp,
            [key]: value,
        });
    }

    function handleFormSubmit(event: any) {
        event.preventDefault();

        let error: string[] = [];
        const emptyFields: string[] = [];

        for (const [key, value] of Object.entries(requestAccessItemTemp)) {
            if (value === "" && (key !== "comment" && key !== "dateCreation" && key !== "id" && key !== "status")) {
                emptyFields.push(key);
            }
        }

        if (emptyFields.length > 0) {
            const fields = emptyFields.map((field: string) => {
                return requestAccessFieldNames.find(item => item.key === field)?.name;
            });
            error.push(ERROR_EMPTY_FIELDS + fields.join(", "));
        }

        if (requestAccessItemTemp.phone && !(requestAccessItemTemp.phone.match(/^\+7\d{10}$/g)![0].length === 12)) {
            error.push(ERROR_PHONE);
        }

        if (requestAccessItemTemp.dateAccessFrom && requestAccessItemTemp.dateAccessTo) {
            const dateFrom = convertStringToDate(requestAccessItemTemp.dateAccessFrom);
            const dateTo = convertStringToDate(requestAccessItemTemp.dateAccessTo);

            console.log(requestAccessItemTemp.dateAccessFrom, requestAccessItemTemp.dateAccessTo);
            console.log(dateFrom, dateTo);

            if (dateFrom.getTime() > dateTo.getTime()) {
                error.push(ERROR_DATE_FROM_TO);
            }
        }

        if (error.length > 0) {
            // чтобы успела подгрузиться картинка
            setTimeout(() => {
                handleAlertOpen("fail", error.join("|"));
            }, 100);
        } else {
            if (action === "create") {
                const currentDate: Date = new Date();
                requestAccessItemTemp.dateCreation = convertDateToString(currentDate);

                setRequestAccessList([...requestAccessList, requestAccessItemTemp]);

                apiHandler.postRequestAccess({
                    setRequestLoading,
                    requestAccessItemTemp,
                    setRequestAccessPosted,
                    setRequestAccessId,
                    handleAlertOpen
                });
            } else {
                if (JSON.stringify(requestAccessItemTemp) !== JSON.stringify(requestAccessCurrent)) {
                    requestAccessList.forEach((item: RequestAccessType, i: number) => {
                        if (item.id === requestAccessItemTemp.id) {
                            requestAccessList[i] = requestAccessItemTemp;
                        }
                    });

                    apiHandler.putRequestAccess({setRequestLoading, requestAccessItemTemp, handleAlertOpen});
                }
            }
        }
    }

    useEffect(() => {
        console.log(requestAccessCurrent);
        pathName === CREATION_LINK ? setAction("create") : pathName === EDIT_LINK && setAction("view");

        if (pathName === CREATION_LINK) {
            // console.log(requestAccessItemDefault);
            // setRequestAccessItemTemp(requestAccessItemDefault);
            localStorage.removeItem(KEY_CURRENT_REQUEST);

            const formElement: HTMLElement | null = document.getElementById("form-access");
            formElement && (formElement as HTMLFormElement).reset();
        }

        apiHandler.getRequestAccessData({setDataListItemsData});
    }, [pathName]);

    useEffect(() => {
        setRequestAccessItemTemp(requestAccessCurrent);
    }, [requestAccessCurrent]);

    return (
        <div className="page__wrapper">
            {isRequestLoading && <SpinnerCustom layout={true}/>}

            <PageTitle title={action === "create" ? "Создание заявки на доступ" : `Заявка №${requestAccessItemTemp.id}`}
                       status={action === "create" ? undefined : requestAccessItemTemp.status}
            />

            <div className="request-access">
                <FormAccess action={action}
                            setAction={setAction}
                            handleFormSubmit={handleFormSubmit}
                            requestAccessCurrent={requestAccessCurrent}
                            requestAccessItem={requestAccessItemTemp}
                            requestAccessStatuses={requestAccessStatuses}
                            dataListItemsData={dataListItemsData}
                            setterRequestAccess={setterRequestAccess}
                            isRequestAccessPosted={isRequestAccessPosted}
                            accessId={requestAccessId}
                            handleAlertOpen={handleAlertOpen}/>
            </div>
        </div>
    );
}

export default RequestAccess;