import {NameValueType} from "../types/name-value.type";

function getItemValue(itemName: string, items: NameValueType[]): string {
    let newItem: NameValueType | undefined;

    if (itemName && items && items.length > 0) {
        newItem = items.find((item: NameValueType) => item.name.toLowerCase() === itemName.toLowerCase());
    }
    if (newItem) {
        return newItem.value.toString();
    } else {
        return "";
    }
}

export default getItemValue;