import {useEffect, useState} from "react";

import {apiHandler} from "../../../shared/utils/ApiHandler";

import SpinnerCustom from "../../components/SpinnerCustom/SpinnerCustom";
import DatalistCustom from "../../components/DatalistCustom/DatalistCustom";
import upFirstLetter from "../../../shared/utils/upFirstLetter";

import {ERROR_EMPTY_FIELDS} from "../../../shared/config/config";
import {requestServiceItemDefault} from "../../../shared/config/default-items/request-service-item-default";
import {requestServiceFieldNames} from "../../../shared/config/request-service-field-names";
import {accountDefault} from "../../../shared/config/default-items/account-default";

import {
    RequestServiceType,
    SetterRequestServiceItemType
} from "../../../shared/types/request-service.type";
import {SensorElementItemType} from "../../../shared/types/sensor-element-item.type";
import {AccountType} from "../../../shared/types/account.type";

import "./RequestService.scss";
import {systemsList} from "../../../shared/config/systemsList";
import {log} from "util";

function RequestService({accountInfo, handleAlertOpen}: {
    accountInfo: AccountType,
    handleAlertOpen: (type: "success" | "fail", text: string) => void
}) {
    const [requestServiceItem, setRequestServiceItem]
        = useState<RequestServiceType>(requestServiceItemDefault);
    const [isRequestLoading, setRequestLoading] = useState<boolean>(false);
    const [sensorsAll, setSensorsAll] = useState<SensorElementItemType[]>([]);
    const [accountData, setAccountData] = useState<AccountType>(accountDefault);

    const setterRequestService = ({key, value}: SetterRequestServiceItemType): void => {
        setRequestServiceItem({
            ...requestServiceItem,
            [key]: value,
        });
    }

    function onDataChange(event: any): void {
        event.target.value
            ? event.target.classList.add("form-item_filled")
            : event.target.classList.remove("form-item_filled");

        setterRequestService({key: event.target.name, value: event.target.value});
    }

    function handleFormSubmit(event: any): void {
        event.preventDefault();

        const elements: HTMLCollectionOf<Element> = document.getElementsByClassName("request-service__item");
        if (elements.length > 0) {
            Array.from(elements).forEach((element: any) => {
                console.log(element.value);

                if (element.value) {
                    requestServiceItem[element.name] = element.value;
                }
            });
        }

        let error: string[] = [];
        const emptyFields: string[] = [];

        for (const [key, value] of Object.entries(requestServiceItem)) {
            console.log(key, value)
            if (value === "" && (key !== "comment" && key !== "id")) {
                emptyFields.push(key);
            }
        }

        if (emptyFields.length > 0) {
            const fields = emptyFields.map((field: string) => {
                return requestServiceFieldNames.find(item => item.key === field)?.name;
            });

            error.push(ERROR_EMPTY_FIELDS + fields.join(", "));
        }

        if (requestServiceItem.system === "3" && requestServiceItem.comment === "") {
            error.push("Необходимо заполнить поле Комментарий");
        }

        if (error.length > 0) {
            // чтобы успела подгрузиться картинка
            setTimeout(() => {
                handleAlertOpen("fail", error.join("|"));
            }, 100);
        } else {
            apiHandler.postRequestService({setRequestLoading, requestServiceItem, handleAlertOpen});
        }
    }

    useEffect(() => {
        apiHandler.getSensorsAll({setSensorsAll});

        const accountId: string = accountInfo.id;
        apiHandler.getAccount({accountId, setAccountData});
    }, []);

    return (
        <div className="request-service">
            {isRequestLoading && <SpinnerCustom layout={true}/>}

            <div className="request-service__wrapper">
                <div className="request-service__title">Рассказать о неисправности</div>

                <form className="form-service" id="form-service" onSubmit={handleFormSubmit}>
                    <input name="org"
                           id="service-org"
                           type="text"
                           className="form-control form-item_shadow request-service__item"
                           placeholder="Организация"
                           defaultValue={accountData.org}
                           autoComplete="off"
                           disabled
                           onChange={onDataChange}/>

                    <input name="fio"
                           id="service-fio"
                           type="text"
                           className="form-control form-item_shadow request-service__item"
                           placeholder="ФИО"
                           defaultValue={accountData.fio}
                           autoComplete="off"
                           disabled
                           onChange={onDataChange}/>

                    <select name="system"
                            className="form-select form-item_shadow request-service__item"
                            defaultValue=""
                            onChange={onDataChange}>
                        <option disabled value="">Системы</option>
                        {systemsList.map((system: string, index: number) => (
                            <option key={index} value={index.toString()}>{system}</option>
                        ))}
                    </select>

                    <textarea name="comment"
                              className="form-control form-item_shadow form-item__comment request-service__item"
                              placeholder="Комментарий"
                              onChange={onDataChange}>
                    </textarea>

                    <button type="submit" className="btn btn-primary w-100" id="service-submit-button">
                        Создать заявку
                    </button>

                </form>
            </div>

            <div className="request-service__text">
                Если остались вопросы, обратитесь в техническую поддержку по номеру +7(915)-670-31-31
            </div>
        </div>
    );
}

export default RequestService;