import successIcon from "../../../assets/images/icons/alert/success.svg";
import failIcon from "../../../assets/images/icons/alert/fail.svg";

import "./AlertCustom.scss";

function AlertCustom({type, text}: { type: "success" | "fail", text: string }) {
    const textArr: string[] = text.split("|");

    return (
        <div className="alertCustom">
            <div className="alertCustom__image">
                <img src={type === "success" ? successIcon : failIcon} alt="Иконка статуса"/>
            </div>

            <div className="alertCustom__message">
                {textArr && textArr.length > 0 && textArr.map((line: string, index: number) => (
                    <div key={index} >
                        {line.split(":").map((item: string, indexItem: number) => (
                            <p key={indexItem} className="alertCustom__text m-0">
                                {line.includes(":") && indexItem === 0 ? item + ": " : item}
                            </p>
                        ))}
                        {index < textArr.length - 1 && <br/>}
                    </div>
                ))}
            </div>

        </div>
    );
}

export default AlertCustom;