import {Dispatch, SetStateAction} from "react";
import Modal from 'bootstrap/js/dist/modal';

import {ID_MODAL_USER} from "../config/config";

class ModalActions {
    openModal(id: string, setModal?: Dispatch<SetStateAction<Modal | null>>): void {
        const modalElement: HTMLElement | null = document.getElementById(id);
        const options: any = id === ID_MODAL_USER ? {
            backdrop: 'static',
            keyboard: false
        } : undefined;

        if (modalElement) {
            const modal: Modal = new Modal(modalElement, options);
            modal.show();
            setModal && setModal(modal);
        }
    }

    closeModal(modal: Modal | null): void {
        modal && modal.hide();
    }

    listenModal(id: string, handleModalClose: () => void) {
        const modalElement: HTMLElement | null = document.getElementById(id);
        if (modalElement) {
            modalElement.addEventListener('hidden.bs.modal', handleModalClose);
            return (() => {
                modalElement.removeEventListener('hidden.bs.modal', handleModalClose);
            });
        }
    }

}

export const modalActions: ModalActions = new ModalActions();