import sortByMkd from "./sortByMkd";

import {MkdItemsType, MkdItemType} from "../types/mkd-items.type";

function sortByAddress(array: MkdItemsType[]): MkdItemsType[] {
    return array.map((address: MkdItemsType) => {
        const mkdItems: MkdItemType[] = sortByMkd([...address.mkdItems]);
        return {org: address.org, mkdItems: mkdItems}
    });
}

export default sortByAddress;