import {NameValueType} from "../types/name-value.type";

function getLevelName(level: string, levels: NameValueType[]): string {
    let levelItem: NameValueType | undefined;

    if (level && levels && levels.length > 0) {
        levelItem = levels.find((item: NameValueType) => item.value === level);
    }
    if (levelItem) {
        return levelItem.name;
    } else {
        return "";
    }
}

export default getLevelName;