import React from 'react';

import {ID_MODAL_APPLY} from "../../../shared/config/config";

interface Props {
    applyModalTitle: string;
    applyModalText: string;
    applyButtonText: string;
    cancelButtonText: string;
    handleApply: (event: any) => void;
    handleCancel: () => void;
}

function ModalApply({applyModalTitle, applyModalText, applyButtonText, cancelButtonText, handleApply, handleCancel}: Props) {
    return (
        <div className="modal fade bg-dark bg-opacity-25" id={ID_MODAL_APPLY} aria-hidden="true">
            <div className="modal-dialog modal-dialog-centered modal-sm">
                <div className="modal-content">
                    <div className="modal-header border-bottom">
                        <h4 className="modal-title text-danger">{applyModalTitle}</h4>
                        <button type="button" className="btn-close" data-bs-dismiss="modal" aria-hidden="true"></button>
                    </div>
                    <div className="modal-body p-4 d-flex align-items-center">
                        <p>{applyModalText}</p>
                    </div>
                    <div className="modal-footer d-flex justify-content-end">
                        <button type="button" className="btn btn-secondary" data-bs-dismiss="modal" onClick={handleCancel}>{cancelButtonText}</button>
                        <button type="button" className="btn btn-primary w-auto" data-bs-dismiss="modal" onClick={handleApply}>{applyButtonText}</button>
                    </div>
                </div>
            </div>
        </div>
    );
}

export default ModalApply;