import {Dispatch, SetStateAction} from "react";

import getUsersIdAccess from "../../../shared/utils/getUsersIdAccess";
import imageUrlToBase64 from "../../../shared/utils/imageUrlToBase64";

import {regexOnlyNumbers} from "../../../shared/config/regex";

import {UidType, UserInfoType} from "../../../shared/types/user-info.type";

import "./FormUserUids.scss";

function FormUserUids({uidName, setUidUrl, setUidName, setQr, userData}: {
    uidName: string,
    setUidUrl: Dispatch<SetStateAction<string>>,
    setUidName: Dispatch<SetStateAction<string>>,
    setQr: Dispatch<SetStateAction<boolean>>,
    userData: UserInfoType,
}) {

    function handleItemEditClick(event: any): void {
        const idAccessCurrent = event.target.id.split("-")[event.target.id.split("-").length - 1];
        const uidCurrent: UidType | undefined = userData.uids.find((item: UidType) => item.idAccess === idAccessCurrent);

        if (uidCurrent && uidCurrent.qrUrl !== "") {
            imageUrlToBase64(uidCurrent.qrUrl).then((data: any) => setUidUrl(data));
            setUidName(`${uidCurrent.idAccess}`);
            setQr(true);
        } else {
            setUidUrl("");
            setUidName("");
            setQr(false);
        }
    }

    return (
        <div className="m-0 px-0 form-label text-secondary uid-wrapper" >
            <div className="d-flex flex-column p-2 border rounded gap-3 form-user-uids overflow-y-auto h-100">
                <p className="text-decoration-underline mb-0">Доступ:</p>
                <ul className="list-group pe-3 h-100">
                    {getUsersIdAccess(userData.uids).map((uidNameItem: any, index: number) => (
                        <li key={index}
                            className={`list-item list-item_edit m-0 px-1 fs-6 
                                ${uidNameItem.replace(regexOnlyNumbers, "") === uidName ? "list-item_current" : ""}`}
                            id={`list-item-edit-${uidNameItem.replace(regexOnlyNumbers, "")}`}
                            title="Двойной клик для получения QR кода"
                            onDoubleClick={handleItemEditClick}>
                            {uidNameItem}
                        </li>
                    ))}
                </ul>
            </div>
        </div>
    );
}

export default FormUserUids;