import {MkdItemsType, MkdItemType} from "../types/mkd-items.type";

function mergeMkdItemsFromAddresses(addresses: MkdItemsType[]): MkdItemType[] {
    let mkdItems: MkdItemType[] = [];
    addresses.forEach((address: MkdItemsType) => {
        if (address.mkdItems && address.mkdItems.length > 0)
            mkdItems = [...mkdItems, ...address.mkdItems];
    });
    return mkdItems;
}

export default mergeMkdItemsFromAddresses;