import {useEffect, useState} from "react";

import Modal from 'bootstrap/js/dist/modal';

import {regexOnlyNumbers} from "../../../shared/config/regex";

import "./QrCode.scss";

function QrCode({accessQrCode, accessId, handleAlertOpen}: {
    accessQrCode: string,
    accessId: string,
    handleAlertOpen: (type: "success" | "fail", text: string) => void
}) {
    const [isPopupOpened, setPopupOpened] = useState<boolean>(false);
    const [isPhoneValid, setPhoneValid] = useState<boolean>(false);
    const [phone, setPhone] = useState<string>("");

    function onPhoneChange(event: any) {
        const value = (event.target as HTMLInputElement).value;
        (event.target as HTMLInputElement).value = value.length < 3 ? "+7" : "+" + value.replace(regexOnlyNumbers, "");
        setPhone(value);
    }

    function handleAddModalOpen() {
        setPopupOpened(true);
    }

    function handleModalClose() {
        setPopupOpened(false);
    }

    function handleQrSend() {
        handleModalClose();
        // чтобы успела подгрузиться картинка
        setTimeout(() => {
            handleAlertOpen("success", "QR код отправлен");
        }, 100);
    }

    useEffect(() => {
        if (phone.length === 12) {
            setPhoneValid(true);
        } else {
            setPhoneValid(false);
        }
    }, [phone]);

    useEffect(() => {
        const modalElement: HTMLElement | null = document.getElementById("qr-modal");

        if (modalElement) {
            if (isPopupOpened) {
                const modal: Modal = new Modal(modalElement);
                modal.show();
            }

            modalElement.addEventListener('hidden.bs.modal', handleModalClose);
            return (() => {
                modalElement.removeEventListener('hidden.bs.modal', handleModalClose);
            });
        }
    }, [isPopupOpened]);

    return (
        <div className="qr-code">
            {accessQrCode !== "" &&
                <div className="d-flex flex-column align-items-center">
                    <img src={accessQrCode} alt="Qr код"/>
                    <a href={accessQrCode}
                       className="btn w-100 qr-code__qr-button mt-2"
                       download={accessId === "" ? `qrcode` : `qrcode-${accessId}`}>
                        Скачать
                    </a>
                    <button type="button" className="btn w-100 qr-code__qr-button mt-1"
                            onClick={handleAddModalOpen}>
                        Отправить QR на телефон
                    </button>
                </div>
            }

            {isPopupOpened &&
                <div className="modal fade bg-dark bg-opacity-50" id="qr-modal" style={{display: "none"}}
                     aria-hidden="true">
                    <div className="modal-dialog modal-dialog-centered modal-sm">
                        <div className="modal-content">
                            <div className="modal-header border-bottom">
                                <h4 className="modal-title">Телефон</h4>
                                <button type="button" className="btn-close" data-bs-dismiss="modal"
                                        aria-label="Close"></button>
                            </div>
                            <div className="modal-body p-4">
                                <input name="qr-phone"
                                       type="text"
                                       className="form-control"
                                       placeholder="Телефон"
                                       autoComplete="off"
                                       maxLength={12}
                                       onFocus={(event) => {
                                           const value = (event.target as HTMLInputElement).value;
                                           (event.target as HTMLInputElement).value = value === "" ? "+7" : value;
                                       }}
                                       onBlur={(event) => {
                                           const value = (event.target as HTMLInputElement).value;
                                           (event.target as HTMLInputElement).value = value.length < 3 ? "" : value;
                                       }}
                                       onChange={onPhoneChange}/>
                            </div>
                            <div className="modal-footer">
                                <button type="button" className="btn btn-secondary" data-bs-dismiss="modal">
                                    Закрыть
                                </button>
                                <button type="button" className="btn btn-primary" disabled={!isPhoneValid}
                                        data-bs-dismiss="modal" onClick={handleQrSend}>
                                    Отправить
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            }

        </div>
    );
}

export default QrCode;