import {Dispatch, SetStateAction, useEffect, useState} from "react";
import {NavigateFunction, useNavigate} from "react-router-dom";

import {apiHandler} from "../../../shared/utils/ApiHandler";

import PopupIncidentsList from "../../components/PopupIncidentsList/PopupIncidentsList";

import {mkdDoubleClickHandler} from "../../../shared/utils/mkdDoubleClickHandler";

import mapPin from "../../../assets/images/icons/map/map-pin.svg"

import {MkdItemType} from "../../../shared/types/mkd-items.type";
import {IncidentItemType} from "../../../shared/types/incident-Item.type";

import './Main.scss';

interface Props {
    mkdItems: MkdItemType[];
    setMkdItemCurrent: Dispatch<SetStateAction<MkdItemType>>;
    incidents: IncidentItemType[];
    setIncidents: Dispatch<SetStateAction<IncidentItemType[]>>
}

function Main({
                  mkdItems,
                  setMkdItemCurrent,
                  incidents,
                  setIncidents
              }: Props) {
    const navigate: NavigateFunction = useNavigate();

    const [isPopupIncidentsListOpen, setPopupIncidentsListOpen] = useState<boolean>(true);

    function onAddressDoubleClick(event: any): void {
        mkdDoubleClickHandler(event, mkdItems, setMkdItemCurrent, navigate);
    }

    function handleClosePopupIncident(event: any): void {
        console.log(event.target.id.split("-")[event.target.id.split("-").length - 1]);
        const idIncident = event.target.id.split("-")[event.target.id.split("-").length - 1];
        const incident: IncidentItemType | undefined = incidents.find((item: IncidentItemType) => item.id === idIncident);

        incident && apiHandler.readIncident({incident, incidents, setIncidents});
    }

    function handleClosePopupIncidentsList(): void {
        setPopupIncidentsListOpen(false);
    }

    function handleReadAllIncidents():void {
        apiHandler.readAllIncidents({incidents, setIncidents});
    }

    useEffect(() => {
        incidents && incidents.length > 0
            ? setPopupIncidentsListOpen(true)
            : handleClosePopupIncidentsList();
    }, [incidents]);

    return (
        <div className="main">
            <div className="mkd-items">
                {mkdItems.map((item: MkdItemType, index: number) => (
                    <div key={index}
                         className={`mkd mkd_${item.id} ${item.incident ? "mkd_incident" : ""}  ${item.disabled ? "mkd_not-allowed" : "mkd_pointer"}`}
                         id={`${item.id}`}
                         style={{left: item.left, top: item.top}}
                         title={item.disabled ? "" : `Двойной клик для просмотра`}
                         onDoubleClick={item.disabled ? () => {} : onAddressDoubleClick}>
                        <img className="mkd__pin-image" src={mapPin} alt="Иконка указателя местоположения"/>
                        <p className="mkd__address">{item.address}</p>
                    </div>
                ))}
            </div>

            {/*<div className="mkd-table">*/}
            {/*    <TableAddresses mkdItems={mkdItems}/>*/}
            {/*</div>*/}

            {(isPopupIncidentsListOpen && incidents.filter(incident => !incident.isRead && incident.danger).length > 0) &&
                <PopupIncidentsList mkdItems={mkdItems}
                                    incidents={incidents.filter(incident => !incident.isRead && incident.danger)}
                                    onClose={handleClosePopupIncidentsList}
                                    onReadAllIncidents={handleReadAllIncidents}
                                    onIncidentItemClose={handleClosePopupIncident}/>}
        </div>
    );
}

export default Main;