import {Dispatch, SetStateAction, useEffect, useState} from "react";

import {apiHandler} from "../../../shared/utils/ApiHandler";

import DatalistCustom from "../DatalistCustom/DatalistCustom";
import InputDateDouble from "../InputDateDouble/InputDateDouble";
import getItemValue from "../../../shared/utils/getItemValue";
import upFirstLetter from "../../../shared/utils/upFirstLetter";
import QrCode from "../QrCode/QrCode";

import {regexOnlyNumbers} from "../../../shared/config/regex";

import {RequestAccessType, SetterRequestAccessItemType} from "../../../shared/types/request-access.type";
import {NameValueType} from "../../../shared/types/name-value.type";
import {RequestAccessDataType} from "../../../shared/types/request-access-data.type";

import "./FormAccess.scss";

interface Props {
    action: "create" | "view" | "edit";
    setAction: Dispatch<SetStateAction<"create" | "view" | "edit">>
    handleFormSubmit: (event: any) => void;
    requestAccessCurrent: RequestAccessType;
    requestAccessItem: RequestAccessType;
    requestAccessStatuses: NameValueType[],
    dataListItemsData: RequestAccessDataType | null,
    setterRequestAccess: ({key, value}: SetterRequestAccessItemType) => void,
    isRequestAccessPosted: boolean,
    accessId: string,
    handleAlertOpen: (type: "success" | "fail", text: string) => void
}

function FormAccess({
                        action,
                        setAction,
                        handleFormSubmit,
                        requestAccessCurrent,
                        requestAccessItem,
                        requestAccessStatuses,
                        dataListItemsData,
                        setterRequestAccess,
                        isRequestAccessPosted,
                        accessId,
                        handleAlertOpen
                    }: Props) {

    const [isDisabled, setDisabled] = useState<boolean>(action === "view");
    const [isDataChanged, setDataChanged] = useState<boolean>(false);
    const [orgs, setOrgs] = useState<string[]>([]);
    const [positions, setPositions] = useState<string[]>([]);
    const [targets, setTargets] = useState<string[]>([]);
    const [accessQrCode, setAccessQqCode] = useState<string>("");
    const [qrCodeError, setQrCodeError] = useState<string | null>(null);

    function onDataListChange(name: string, value: string): void {
        setterRequestAccess({key: name, value: value});
    }

    function onDoubleDateChange(name: "from" | "to" | "single", value: string): void {
        if (name === "from") {
            setterRequestAccess({key: "dateAccessFrom", value: value});
            requestAccessItem.dateAccessFrom = value;
        } else {
            setterRequestAccess({key: "dateAccessTo", value: value});
            requestAccessItem.dateAccessTo = value;
        }
    }

    function onPhoneChange(event: any) {
        const value = (event.target as HTMLInputElement).value;
        (event.target as HTMLInputElement).value = value.length < 3 ? "+7" : "+" + value.replace(regexOnlyNumbers, "");

        value.length === 12 && setterRequestAccess({key: "phone", value: value});
    }

    function onDataChange(event: any): void {
        setterRequestAccess({key: event.target.name, value: event.target.value});
    }

    function findIsDataChanged() {
        if (JSON.stringify(requestAccessItem) !== JSON.stringify(requestAccessCurrent)) {
            setDataChanged(true);
        } else {
            setDataChanged(false);
        }
    }

    function handleQrButtonClick() {
        apiHandler.getAccessQqCode({accessId, setAccessQqCode, setQrCodeError});
    }

    useEffect(() => {
        action === "view" ? setDisabled(true) : setDisabled(false);
        setQrCodeError(null);
        setAccessQqCode("");
    }, [action]);

    useEffect(() => {
        console.log("changed")
        findIsDataChanged();
    }, [requestAccessItem]);

    useEffect(() => {
        const targetElement: HTMLElement | null = document.getElementById("access-target");

        if (targetElement && action !== "create") {
            (targetElement as HTMLSelectElement).value = requestAccessItem.target;
        }
    }, [targets, requestAccessItem]);

    useEffect(() => {
        if (dataListItemsData) {
            dataListItemsData.orgs && dataListItemsData.orgs.length > 0 && setOrgs(dataListItemsData.orgs);
            dataListItemsData.positions && dataListItemsData.positions.length > 0 && setPositions(dataListItemsData.positions);
            dataListItemsData.targets && dataListItemsData.targets.length > 0 && setTargets(dataListItemsData.targets);
        }
    }, [dataListItemsData]);

    useEffect(() => {
        setDisabled(isRequestAccessPosted);
    }, [isRequestAccessPosted]);

    return (
        <form className="form-access p-4" id="form-access" onSubmit={handleFormSubmit}>
            <div className="form-access__top">
                <div className="form-access__left">
                    <label className="form-item w-100">
                        <DatalistCustom items={orgs}
                                        id="org"
                                        placeholder="Организация"
                                        disabled={isDisabled}
                                        filter={true}
                                        defaultValue={requestAccessItem.org ? requestAccessItem.org : ""}
                                        onChange={onDataListChange}/>
                    </label>

                    <input name="fio"
                           type="text"
                           className="form-control form-item"
                           placeholder="ФИО представителя"
                           defaultValue={requestAccessItem.fio ? requestAccessItem.fio : ""}
                           disabled={isDisabled}
                           autoComplete="off"
                           onChange={onDataChange}/>


                    <label className="form-item w-100">
                        <DatalistCustom items={positions}
                                        id="position"
                                        placeholder="Должность"
                                        disabled={isDisabled}
                                        filter={true}
                                        defaultValue={requestAccessItem.position ? requestAccessItem.position : ""}
                                        onChange={onDataListChange}/>
                    </label>

                    <input name="phone"
                           type="text"
                           className="form-control form-item"
                           placeholder="Телефон представителя"
                           defaultValue={requestAccessItem.phone ? requestAccessItem.phone : ""}
                           disabled={isDisabled}
                           autoComplete="off"
                           maxLength={12}
                           onFocus={(event) => {
                               const value = (event.target as HTMLInputElement).value;
                               (event.target as HTMLInputElement).value = value === "" ? "+7" : value;
                           }}
                           onBlur={(event) => {
                               const value = (event.target as HTMLInputElement).value;
                               (event.target as HTMLInputElement).value = value.length < 3 ? "" : value;
                           }}
                           onChange={onPhoneChange}/>

                    <select name="target"
                            id="access-target"
                            className={`form-select form-item ${requestAccessItem?.target === "" ? "form-select_default" : ""}`}
                            defaultValue={requestAccessItem.target ? upFirstLetter(requestAccessItem.target) : ""}
                            disabled={isDisabled}
                            onChange={onDataChange}>
                        <option disabled value="">Цель доступа</option>
                        {targets.map((target: string, index: number) => (
                            <option key={index} value={target}>{upFirstLetter(target)}</option>
                        ))}
                    </select>

                    <div className="form-item">
                        <InputDateDouble action={action}
                                         defaultDateFrom={requestAccessItem.dateAccessFrom && requestAccessItem.dateAccessFrom}
                                         defaultDateTo={requestAccessItem.dateAccessTo && requestAccessItem.dateAccessTo}
                                         disabled={isDisabled}
                                         onChange={onDoubleDateChange}/>

                    </div>

                    <div className="form-access__comment">
                        <textarea name="comment"
                                  className="form-control"
                                  id="input-comment"
                                  defaultValue={requestAccessItem.comment ? requestAccessItem.comment : ""}
                                  disabled={isDisabled}
                                  onChange={onDataChange}>
                        </textarea>
                        <span>0 / 300</span>
                    </div>

                    {action === "create" &&
                        <>
                            <button type="submit" className="btn btn-primary w-100 form-item"
                                    id="access-submit-button" disabled={isRequestAccessPosted}>
                                Создать заявку
                            </button>
                            {isRequestAccessPosted &&
                                <button type="button" className="btn w-100 form-access__qr-button form-item"
                                        id="access-qr-button" onClick={handleQrButtonClick}>
                                    Получить QR код
                                </button>
                            }
                        </>
                    }
                </div>

                <div className={`form-access__right ${action === "create" ? "d-flex justify-content-center" : ""}`}>
                    {action !== "create"
                        ? <>
                            <select name="status"
                                    className="form-select form-item form-access__status"
                                    defaultValue={requestAccessItem.status ? requestAccessItem.status : ""}
                                    onChange={onDataChange}>
                                {requestAccessStatuses.map((status: NameValueType, index: number) => (
                                    <option className={`form-access__status-option 
                                            ${requestAccessItem.status === status.name ? "form-access__status-option_" + status.value : ""}`}
                                            key={index}
                                            value={status.name}>
                                        {upFirstLetter(status.name)}
                                    </option>
                                ))}
                            </select>
                            <button type="button"
                                    className="btn btn-light w-100 mb-3 form-item"
                                    id="access-submit-button"
                                    onClick={() => setAction("edit")}>
                                Редактировать заявку
                            </button>

                            {accessQrCode === "" &&
                                <button type="button"
                                        className="btn w-100 form-access__qr-button form-item"
                                        id="access-qr-button" onClick={handleQrButtonClick}>
                                    Получить QR код
                                </button>
                            }

                            <QrCode accessQrCode={accessQrCode} accessId={accessId} handleAlertOpen={handleAlertOpen}/>
                        </>

                        : <QrCode accessQrCode={accessQrCode} accessId={accessId} handleAlertOpen={handleAlertOpen}/>
                    }
                </div>

            </div>

            {action !== "create" &&
                <button type="submit" className="btn btn-primary w-100 form-item" id="access-submit-button"
                        disabled={!isDataChanged}>
                    Сохранить
                </button>
            }
        </form>
    );
}

export default FormAccess;
