import {Dispatch, SetStateAction, useEffect} from "react";

import {apiHandler} from "../../../shared/utils/ApiHandler";

import TableSensors from "../../components/TableSensors/TableSensors";
import PageTitle from "../../components/PageTitle/PageTitle";
import ItemDetector from "../../components/ItemDetector/ItemDetector";

import getLevelName from "../../../shared/utils/getLevelName";

import basementPlan from "../../../assets/images/basement.svg";
import floorPlan from "../../../assets/images/floor.svg";
import atticPlan from "../../../assets/images/attic.svg";

import atticRoofEnter from "../../../assets/images/layouts/attic-roof-enter.svg";
import atticEnter from "../../../assets/images/layouts/attic-enter.svg";
import floorVault from "../../../assets/images/layouts/floor-vault.svg";
import basementColdWater from "../../../assets/images/layouts/basement-cold-water.svg";
import basementHotWater from "../../../assets/images/layouts/basement-hot-water.svg";
import basementTrash from "../../../assets/images/layouts/basement-trash.svg";
import basementEnter1 from "../../../assets/images/layouts/basement-enter-1.svg";
import basementEnter2 from "../../../assets/images/layouts/basement-enter-2.svg";

import {MkdItemType} from "../../../shared/types/mkd-items.type";
import {IncidentItemType} from "../../../shared/types/incident-Item.type";
import {SensorElementItemType} from "../../../shared/types/sensor-element-item.type";
import {VideoElementItemType} from "../../../shared/types/video-element-item.type";
import {NameValueType} from "../../../shared/types/name-value.type";

import "./Floor.scss";

interface Props {
    mkdItemCurrent: MkdItemType;
    levelItemCurrent: string;
    levels: NameValueType[];
    incidents: IncidentItemType[];
    sensorItems: SensorElementItemType[];
    videoItems: VideoElementItemType[];
    setLevelsMkd: Dispatch<SetStateAction<NameValueType[]>>;
    setSensorLevelItems: Dispatch<SetStateAction<SensorElementItemType[]>>;
    setVideoLevelItems: Dispatch<SetStateAction<VideoElementItemType[]>>;
    setLoading: Dispatch<SetStateAction<boolean>>;
}

function Floor({
                   mkdItemCurrent,
                   levelItemCurrent,
                   levels,
                   incidents,
                   sensorItems,
                   videoItems,
                   setLevelsMkd,
                   setSensorLevelItems,
                   setVideoLevelItems,
                   setLoading
               }: Props) {

    const atticLayouts: {name: string, src: string}[] = [
        {name: "atticRoofEnter", src: atticRoofEnter},
        {name: "atticEnter", src: atticEnter}];
    const floorLayouts: {name: string, src: string}[] = [
        {name: "floorVault", src: floorVault}];
    const basementLayouts: {name: string, src: string}[] = [
        {name: "basementColdWater", src: basementColdWater},
        {name: "basementHotWater", src: basementHotWater},
        {name: "basementTrash", src: basementTrash},
        {name: "basementEnter1", src: basementEnter1},
        {name: "basementEnter2", src: basementEnter2}];

    function findIsElementsCollide(childText: Element, childrenIcon: NodeListOf<Element>, childrenText: NodeListOf<Element>) {
        let i = 0;

        while (i < 4) {
            let isCollideAnyone = false;

            [...Array.from(childrenIcon), ...Array.from(childrenText)].forEach(child => {
                if (childText !== child) {
                    const rect1 = childText.getBoundingClientRect();
                    const rect2 = child.getBoundingClientRect();

                    const isCollide = !(
                        rect1.top > rect2.bottom ||
                        rect1.right < rect2.left ||
                        rect1.bottom < rect2.top ||
                        rect1.left > rect2.right
                    );

                    if (isCollide) {
                        isCollideAnyone = true;
                    }
                }
            });

            if (isCollideAnyone && i === 0) {
                (childText as HTMLElement).style.left = `26px`;
                (childText as HTMLElement).style.top = `-26px`;
            }

            if (isCollideAnyone && i === 1) {
                (childText as HTMLElement).style.left = `-30%`;
                (childText as HTMLElement).style.top = `-46px`;
            }

            if (isCollideAnyone && i === 2) {
                (childText as HTMLElement).style.left = "-100%";
                (childText as HTMLElement).style.top = `-26px`;
            }

            i++;
        }
    }

    useEffect(() => {
        const planElement = document.getElementById("floor-plan");

        if (planElement) {
            const childrenIcon = planElement.querySelectorAll(".item-detector__icon");
            const childrenText = planElement.querySelectorAll(".item-detector__text");

            Array.from(childrenText).forEach(childText => {
                findIsElementsCollide(childText, childrenIcon, childrenText);
            });
        }

    }, [sensorItems, videoItems]);

    useEffect(() => {
        const idMkd: string = mkdItemCurrent.id;

        apiHandler.getLevelSensorItems({setLoading, idMkd, levelItemCurrent, setSensorLevelItems});
        apiHandler.getLevelVideoItems({setLoading, idMkd, levelItemCurrent, setVideoLevelItems});
        apiHandler.getMkdLevels({idMkd, setLevelsMkd});
    }, [levelItemCurrent]);

    useEffect(() => {
        console.log(sensorItems);
    }, [sensorItems]);

    return (
        <div className="floor">
            <PageTitle
                title={`г.Москва, ${mkdItemCurrent && mkdItemCurrent.address}, ${getLevelName(levelItemCurrent, levels)}`}/>
            <div className="floor__content">
                <div className="floor__plan" id="floor-plan">
                    <img src={levelItemCurrent === "0"
                        ? basementPlan
                        : levelItemCurrent === "2"
                            ? atticPlan
                            : floorPlan}
                         alt="План этажа"/>

                    {(levelItemCurrent === "0"
                        ? basementLayouts
                        : levelItemCurrent === "2"
                            ? atticLayouts
                            : floorLayouts).map((item: { name: string, src: string }, index: number) => (
                        <img key={index} className={`floor__layout floor__layout_${item.name}`} src={item.src} alt="Слой"/>
                    ))}

                    {sensorItems && sensorItems.length > 0 && sensorItems.map((item: SensorElementItemType, index: number) => {
                        return <ItemDetector item={item} key={index} position="absolute"/>
                    })}

                    {videoItems && videoItems.length > 0 && videoItems.map((item: VideoElementItemType, index: number) => {
                        return <ItemDetector item={item} key={index} position="absolute"/>
                    })}

                </div>
                <div className="floor__table">
                    <TableSensors sensorItems={sensorItems}/>
                </div>
            </div>
        </div>
    );
}

export default Floor;