import {Dispatch, SetStateAction} from "react";
import {NavigateFunction, useNavigate} from "react-router-dom";

import {mkdDoubleClickHandler, setMkdItem} from "../../../shared/utils/mkdDoubleClickHandler";
import mergeMkdItemsFromAddresses from "../../../shared/utils/mergeMkdItemsFromAddresses";
import collapseAccordionItems from "../../../shared/utils/collapseAccordionItems";
import levelDoubleClickHandler from "../../../shared/utils/levelDoubleClickHandler";
import upFirstLetter from "../../../shared/utils/upFirstLetter";
import getItemValue from "../../../shared/utils/getItemValue";

import {MONITORING_LINK} from "../../../shared/config/config";

import {MkdItemsType, MkdItemType} from "../../../shared/types/mkd-items.type";
import {NameValueType} from "../../../shared/types/name-value.type";

import './AccordionAddress.scss';


interface Props {
    mkdItems: MkdItemType[];
    setMkdItemCurrent: Dispatch<SetStateAction<MkdItemType>>;
    levels: NameValueType[];
    searchedAddresses: MkdItemsType[];
}

function AccordionAddress({mkdItems, setMkdItemCurrent, levels, searchedAddresses}: Props) {
    const navigate: NavigateFunction = useNavigate();

    function handleMainButtonClick(): void {
        const buttonMapElement: Element | null = document.getElementById("map-button");
        if (buttonMapElement) {
            buttonMapElement.classList.remove("collapsed");
            collapseAccordionItems(buttonMapElement);
        }

        navigate(MONITORING_LINK);
    }

    function handleMkdButtonClick(): void {
        const buttonMapElement: HTMLElement | null = document.getElementById("map-button");
        if (buttonMapElement) {
            buttonMapElement.classList.add("collapsed");
        }
    }

    function handleMkdButtonDoubleClick(event: any): void {
        event.target.classList.remove("collapsed");
        document.getElementById(`collapse-mkd-${event.target.id.replace(/\D/g, "")}`)?.classList.add("show");

        mkdDoubleClickHandler(event, mergeMkdItemsFromAddresses(searchedAddresses), setMkdItemCurrent, navigate);
    }

    function handleLevelButtonDoubleClick(event: any): void {
        setMkdItem(event, mergeMkdItemsFromAddresses(searchedAddresses), setMkdItemCurrent);
        levelDoubleClickHandler(event, mkdItems, navigate);
    }

    return (
        <div className="accordion accordion-flush" id="accordion">
            <div className="accordion-item">
                <h2 className="accordion-header">
                    <button className="accordion-button accordion-button_hide-icon"
                            id="map-button"
                            type="button" onClick={handleMainButtonClick}>
                        Карта
                    </button>
                </h2>
            </div>
            {searchedAddresses.map((item: MkdItemsType, index: number) => (
                <div key={index} className="accordion-item">
                    <h2 className="accordion-header">
                        <button key={index}
                                className="accordion-button mkd-items__button"
                                id={`org-button-${index}`}
                                type="button" data-bs-toggle="collapse"
                                data-bs-target={`#collapse-org-${index}`} aria-expanded="true"
                                aria-controls={`collapse-org-${index}`}>
                            {item.org}
                        </button>
                    </h2>
                    <div id={`collapse-org-${index}`} className="accordion-collapse collapse mkd-items__collapse show"
                         data-bs-parent="#accordion">
                        <div className="accordion accordion-flush accordion_mkd" id="accordion-mkd-items">
                            {item.mkdItems.map((item: MkdItemType, index: number) => (
                                <div className={`accordion-item mkd mkd_${item.id}`} key={index}>
                                    <h2 className="accordion-header">
                                        <button
                                            className={`accordion-button collapsed mkd__button mkd__button_${item.id}
                                            ${item.incident ? "mkd__button_incident" : ""}`}
                                            id={`mkd-button-${item.id}`}
                                            type="button" data-bs-toggle="collapse"
                                            data-bs-target={`#collapse-mkd-${item.id}`}
                                            aria-expanded="false"
                                            aria-controls={`collapse-mkd-${item.id}`}
                                            disabled={item.disabled}
                                            onClick={handleMkdButtonClick}
                                            onDoubleClick={handleMkdButtonDoubleClick}>
                                            {item.name}
                                        </button>
                                    </h2>
                                    <div id={`collapse-mkd-${item.id}`}
                                         className="accordion-collapse collapse">
                                        <div className="accordion-body items-in">
                                            {item.levels && item.levels.map((level: string, index: number) => (
                                                <div
                                                    key={index}
                                                    className={`item-in item-in_${item.id}
                                                        ${item.incident && item.incidentLevels?.includes(level) ? "item-in_incident" : ""}`}
                                                    id={`item-in-${item.id}-${getItemValue(level, levels)}`}
                                                    onDoubleClick={handleLevelButtonDoubleClick}>
                                                    {upFirstLetter(level)}
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            ))}
        </div>
    );
}

export default AccordionAddress;