import {useNavigate} from "react-router-dom";

import upFirstLetter from "../../../shared/utils/upFirstLetter";

import arrow from "../../../assets/images/icons/left-arrow-primary.svg";

import "./PageTitle.scss";

function PageTitle({title, status}: { title: string, status?: "черновик" | "в работе" | "завершена" | "отменена" }) {
    const navigate = useNavigate();

    return (
        <div className="page-title px-4 py-3">
            <button className="page-title__link" onClick={() => navigate(-1)}>
                <img src={arrow} alt="Стрелка влево"/>
                Назад
            </button>
            <div className="page-title__title">
                {title}
                {status &&
                    <span className={`page-title__status                     
                        ${status === "черновик"
                        ? "page-title__status_draft"
                        : status === "в работе"
                            ? "page-title__status_progress"
                            : status === "завершена"
                                ? "page-title__status_finished"
                                : "page-title__status_cancel"}`}>
                        {upFirstLetter(status)}
                    </span>}
            </div>
        </div>
    )
}

export default PageTitle;