import {UidType} from "../types/user-info.type";

function getUsersIdAccess(uids: UidType[]): string[] {
    const idAccessItems: string[] = Array.from(new Set(uids.map((item: UidType) => item.idAccess)));

    const uidNameItems: string[] = idAccessItems.map((item: string) =>
        item === "" ? "Постоянный" : `Временный (заявка ${item})`
    );

    return uidNameItems;
}

export default getUsersIdAccess;