import {useEffect, useState} from "react";

import {modalActions} from "../../../shared/utils/ModalActions";

import ModalWebCam from "../ModalWebCam/ModalWebCam";

import {ID_MODAL_WEBCAM} from "../../../shared/config/config";

import photoDefault from "../../../assets/images/photo.png";
import plusIcon from "../../../assets/images/icons/plus-circle.svg";
import editIcon from "../../../assets/images/icons/edit-circle.svg";

import {UserInfoType} from "../../../shared/types/user-info.type";

import "./FormUserPhoto.scss";

function FormUserPhoto({initialUserData, setterUserDataTemp, userAction}: {
    initialUserData: UserInfoType,
    setterUserDataTemp: ({name, value}: { [key: string]: string }) => void,
    userAction: "add" | "edit" | "delete";
}) {
    const [photo, setPhoto] = useState<string>(photoDefault);
    const [isPhoto, setIsPhoto] = useState<boolean>(false);
    const [isChange, setChange] = useState<boolean>(false);
    const [isErrorModalActive, setErrorModalActive] = useState<boolean>(false);
    const [errorModalTitle, setErrorModalTitle] = useState<string>("");
    const [errorModalText, setErrorModalText] = useState<string>("");
    const [isWebCamModalActive, setWebCamModalActive] = useState<boolean>(false);
    const [photoFromCamera, setPhotoFromCamera] = useState<string>("");

    const photoWidth: number = 145;
    const photoHeight: number = 192;

    function base64toBlob(
        b64Data: string,
        contentType: string = '',
        sliceSize: number = 512,
    ): Blob {
        const byteCharacters = atob(b64Data);
        const byteArrays = [];

        for (let offset = 0; offset < byteCharacters.length; offset += sliceSize) {
            const slice = byteCharacters.slice(offset, offset + sliceSize);

            const byteNumbers = new Array(slice.length);
            for (let i = 0; i < slice.length; i++) {
                byteNumbers[i] = slice.charCodeAt(i);
            }

            const byteArray = new Uint8Array(byteNumbers);
            byteArrays.push(byteArray);
        }
        return new Blob(byteArrays, {type: contentType});
    }

    function handleSetWebCamPhoto(): void {
        const camPhoto = document.getElementById("photo");
        if (camPhoto) {
            const base64Photo = (camPhoto as HTMLImageElement).src;
            const blobImg = base64toBlob(base64Photo.split(",")[1]);
            const objectURL: string = URL.createObjectURL(blobImg);

            setPhoto(objectURL);
            setIsPhoto(true);
            setterUserDataTemp({name: "photoUrl", value: objectURL});
        }
    }

    function handleSetFilePhoto(event: any): void {
        if (event.currentTarget.files) {
            const file: File = event.currentTarget.files[0];

            if (file) {
                const fileFormat: string = file.name.slice(file.name.lastIndexOf('.') + 1);
                if (file.size / 1024 / 1024 > 2) {
                    setErrorModalActive(true);
                    setErrorModalTitle("Ошибка");
                    setErrorModalText("Размер файла не должен превышать 2мб");
                } else if (fileFormat !== "jpg" && fileFormat !== "jpeg" && fileFormat !== "png" && fileFormat !== "svg") {
                    setErrorModalActive(true);
                    setErrorModalTitle("Ошибка");
                    setErrorModalText("Файл должен иметь расширение jpeg, jpg, png, svg");
                } else {
                    const fileSrc: string = URL.createObjectURL(file);

                    setPhoto(fileSrc);
                    setIsPhoto(true);
                    setterUserDataTemp({name: "photoUrl", value: fileSrc});
                }
            }
        }
    }

    function handleRemovePhoto(): void {
        setPhoto(photoDefault);
        setIsPhoto(false);
        setterUserDataTemp({name: "photoUrl", value: ""});
    }

    function handleImgChangeButtonClick(event: any): void {
        event.stopPropagation();
        event.preventDefault();
        setChange(!isChange);
    }

    function handleWebCamModalOpen(): void {
        setWebCamModalActive(true);
    }

    function handleWebCamModalClose(): void {
        setWebCamModalActive(false);
    }

    useEffect(() => {
        if (initialUserData.photoUrl !== "") {
            setPhoto(initialUserData.photoUrl);
            setIsPhoto(true);
        } else {
            setPhoto(photoDefault);
            setIsPhoto(false);
        }
    }, [initialUserData.photoUrl]);

    useEffect(() => {
        if (isWebCamModalActive) {
            modalActions.openModal(ID_MODAL_WEBCAM);
            modalActions.listenModal(ID_MODAL_WEBCAM, handleWebCamModalClose);
        }
    }, [isWebCamModalActive]);

    return (
        <div className="photo-wrapper border rounded" style={{width: `${photoWidth}px`, height: `${photoHeight}px`}}>
            <img src={photo} alt="Аватар пользователя"
                 onError={() => setPhoto(photoDefault)}
                 className="w-100 h-100 object-fit-cover rounded"
                 style={{overflowClipMargin: "unset"}}/>

            {!isPhoto
                ? <div className="dropdown-center photo-dropdown" style={{width: `${photoWidth}px`, height: `${photoHeight}px`}}>
                    <a href="#" className="w-100 h-100" type="button" data-bs-toggle="dropdown"
                       aria-expanded="false">
                        <img src={plusIcon} alt="Иконка добавления фото"
                             className="icon add-icon"/>
                    </a>
                    <ul className="dropdown-menu">
                        <label className="dropdown-item fs-6 mb-2">
                            Выбрать файл
                            <input
                                className="form-control d-none"
                                id='photo-add'
                                type='file'
                                name='photoAdd'
                                onChange={handleSetFilePhoto}
                            />
                        </label>
                        <button className="dropdown-item fs-6 m-0" onClick={handleWebCamModalOpen}>
                            Сделать снимок
                        </button>
                    </ul>
                </div>
                : <div className="dropdown-center photo-dropdown w-100 h-100">
                    <a href="#" className="w-100 h-100" type="button" data-bs-toggle="dropdown"
                       aria-expanded="false" data-bs-auto-close="false">
                        <img src={editIcon} alt="Иконка редактирования фото"
                             className="icon edit-icon"/>
                    </a>
                    <ul className="dropdown-menu">
                        <button className="dropdown-item fs-6 m-0" onClick={handleImgChangeButtonClick}>
                            Изменить изображение
                        </button>
                        {isChange &&
                            <ul>
                                <label className="dropdown-item fs-6 mb-0">
                                    Выбрать файл
                                    <input
                                        className="form-control d-none"
                                        id='photo-add'
                                        type='file'
                                        name='photoAdd'
                                        onChange={handleSetFilePhoto}
                                    />
                                </label>
                                <button className="dropdown-item fs-6 m-0" onClick={handleWebCamModalOpen}>
                                    Сделать снимок
                                </button>
                            </ul>

                        }
                        <button className="dropdown-item fs-6 m-0" onClick={handleRemovePhoto}>
                            Удалить изображение
                        </button>
                    </ul>
                </div>
            }

            {isWebCamModalActive &&
                <ModalWebCam photoWidth={photoWidth} handlePhotoLoad={handleSetWebCamPhoto}/>
            }
        </div>
    );
}

export default FormUserPhoto;