import {NavigateFunction, useNavigate} from "react-router-dom";

import PopupIncident from "../PopupIncident/PopupIncident";

import {HISTORY_LINK} from "../../../shared/config/config";

import {IncidentItemType} from "../../../shared/types/incident-Item.type";
import {MkdItemType} from "../../../shared/types/mkd-items.type";

import "./PopupIncidentsList.scss"

interface Props {
    mkdItems: MkdItemType[];
    incidents: IncidentItemType[];
    onClose: () => void;
    onReadAllIncidents: () => void;
    onIncidentItemClose: (event: any) => void;
}

function PopupIncidentsList({mkdItems, incidents, onClose, onReadAllIncidents, onIncidentItemClose}: Props) {
    const navigate: NavigateFunction = useNavigate();

    return (
        <>
            {incidents &&
                <>
                    {incidents.length === 1 && incidents[0]
                        ? <PopupIncident mkdItems={mkdItems}
                                         incidentItem={incidents[0]}
                                         position="absolute"
                                         onClose={onIncidentItemClose}/>
                        : <div className="popup-incidents">
                            <div className="popup-incidents__top">
                                <div className="popup-incidents__title">Оповещения</div>
                                <div className="popup-incidents__actions">
                                    <button className="btn btn-light popup-incidents__button"
                                            onClick={onReadAllIncidents}>Прочитать
                                        все
                                    </button>
                                    <button className="popup-incidents__close-button" onClick={onClose}></button>
                                </div>
                            </div>

                            <div className="popup-incidents__body" id="popup-incidents-body">
                                {incidents && incidents.length > 1 &&
                                    incidents.map((incidentItem: IncidentItemType, index: number) => (
                                        <PopupIncident key={index}
                                                       mkdItems={mkdItems}
                                                       incidentItem={incidentItem}
                                                       position="relative"
                                                       onClose={onIncidentItemClose} />
                                    ))}
                            </div>

                            <div className="popup-incidents__bottom">
                                <button className="btn btn-light popup-incidents__button w-100"
                                        onClick={() => navigate(HISTORY_LINK)}>Смотреть все
                                </button>
                            </div>

                        </div>
                    }
                </>
            }
        </>
    );
}

export default PopupIncidentsList;