import {NavigateFunction} from "react-router-dom";

import {KEY_CURRENT_LEVEL, KEY_CURRENT_MKD, MKD_LINK} from "../config/config";
import {regexOnlyNumbers} from "../config/regex";

import {MkdItemType} from "../types/mkd-items.type";
import {Dispatch, SetStateAction} from "react";

export function setMkdItem(event: any,
                           mkdItems: MkdItemType[],
                           setMkdItemCurrent: Dispatch<SetStateAction<MkdItemType>>): void {
    const currentId = event.currentTarget.id.replace(regexOnlyNumbers, "");
    let currentItem: MkdItemType | undefined = mkdItems.find((item: MkdItemType) => item.id === currentId);

    currentItem && localStorage.setItem(KEY_CURRENT_MKD, JSON.stringify(currentItem));
    currentItem && setMkdItemCurrent(currentItem);
    localStorage.removeItem(KEY_CURRENT_LEVEL);
}

export function mkdDoubleClickHandler(event: any,
                                      mkdItems: MkdItemType[],
                                      setMkdItemCurrent: Dispatch<SetStateAction<MkdItemType>>,
                                      navigate: NavigateFunction): void {
    setMkdItem(event, mkdItems, setMkdItemCurrent);
    navigate(MKD_LINK);
}
