import React, {Dispatch, SetStateAction, useEffect, useState} from "react";

import Modal from 'bootstrap/js/dist/modal';

import {apiHandler} from "../../../shared/utils/ApiHandler";
import {modalActions} from "../../../shared/utils/ModalActions";

import FormUser from "../FormUser/FormUser";

import SpinnerCustom from "../SpinnerCustom/SpinnerCustom";

import {ERROR_EMPTY_FIELDS, ERROR_PHONE, ID_MODAL_APPLY, ID_MODAL_USER} from "../../../shared/config/config";
import {userDefault} from "../../../shared/config/default-items/user-default";
import {userDataFieldNames} from "../../../shared/config/user-data-field-names";

import {UserInfoType} from "../../../shared/types/user-info.type";

import "./ModalUser.scss";
import ModalApply from "../ModalApply/ModalApply";

interface Props {
    userId: string;
    userAction: "add" | "edit" | "delete";
    setUserAction: Dispatch<SetStateAction<"add" | "edit" | "delete">>
    onClose: (isDataChanged: boolean) => void;
    handleAlertOpen: (type: "success" | "fail", text: string) => void;
    isLoading: boolean;
    setLoading: Dispatch<SetStateAction<boolean>>;
}

function ModalUser({
                       userId,
                       userAction,
                       setUserAction,
                       onClose,
                       handleAlertOpen,
                       isLoading,
                       setLoading,
                   }: Props) {

    const [userData, setUserData] = useState<UserInfoType>(userDefault);
    const [initialUserData, setInitialUserData] = useState<UserInfoType>(userData);
    const [isUserLoading, setUserLoading] = useState<boolean>(false);
    const [isUserDataChanged, setUserDataChanged] = useState<boolean>(false);
    const [isApplyModalActive, setApplyModalActive] = useState<boolean>(false);
    const [applyModalTitle, setApplyModalTitle] = useState<string>("");
    const [applyModalText, setApplyModalText] = useState<string>("");

    const setterUserDataTemp = ({name, value}: { [key: string]: any }): void => {
        setUserData({
            ...userData,
            [name]: value,
        });
    }

    function handleApplyModalOpen(titleApply: string, textApply: string): void {
        setApplyModalActive(true);
        setApplyModalTitle(titleApply);
        setApplyModalText(textApply);
    }

    function handleApplyModalClose(): void {
        setApplyModalActive(false);
    }

    function handleUserModalCloseButtonClick(): void {
        if (isUserDataChanged) {
            handleApplyModalOpen("Изменения", "Сохранить изменения?")
        } else {
            onClose(false);
        }
    }

    function handleDeleteUser() {
        setUserAction("delete");
        handleApplyModalOpen("Удаление", "Удалить пользователя?");
    }

    function submit(event: any): void {
        event.preventDefault();

        let error: string[] = [];
        const emptyFields: string[] = [];

        for (const [key, value] of Object.entries(userData)) {
            if (value === "" && (key !== "note" && key !== "id" && key !== "photoUrl")) {
                emptyFields.push(key);
            }
        }

        if (emptyFields.length > 0) {
            const fields = emptyFields.map((field: string) => {
                return userDataFieldNames.find(item => item.key === field)?.name;
            });

            error.push(ERROR_EMPTY_FIELDS + fields.join(", "));
        }

        if (userData.phone.length !== 12) {
            error.push(ERROR_PHONE);
        }

        if (error.length > 0) {
            // чтобы успела подгрузиться картинка
            setTimeout(() => {
                handleAlertOpen("fail", error.join("|"));
            }, 100);
        } else {
            userAction == "add" &&
            apiHandler.addUser({
                userData,
                setUserLoading,
                setUserAction,
                setUserData,
                setInitialUserData,
                handleAlertOpen
            });

            userAction == "edit" &&
            apiHandler.editUser({
                userData,
                setUserLoading,
                setUserAction,
                setUserData,
                setInitialUserData,
                handleAlertOpen
            });
        }
    }

    function deleteUser() {
        onClose(true);
        apiHandler.deleteUser({
            userId,
            setLoading,
            onClose,
            handleAlertOpen
        });
    }

    useEffect((): void => {
        if (userAction === "edit" && userId !== "") {
            apiHandler.getUser({
                userId, setUserLoading, setUserAction, setUserData, setInitialUserData, handleAlertOpen
            });
        } else if (userAction === "add" && userId === "") {
            setUserData(userDefault);
            setInitialUserData(userDefault);
        }
    }, [userAction]);


    useEffect((): void => {
        setUserDataChanged(JSON.stringify(userData) !== JSON.stringify(initialUserData));
    }, [userData]);

    useEffect(() => {
        if (isApplyModalActive) {
            modalActions.openModal(ID_MODAL_APPLY);
            modalActions.listenModal(ID_MODAL_APPLY, handleApplyModalClose);
        }
    }, [isApplyModalActive]);

    return (
        <>
            <div className="modal fade" id={ID_MODAL_USER} style={{display: "none"}} data-bs-backdrop="static"
                 aria-hidden="true">
                <div className="modal-dialog modal-dialog-centered modal-xl" style={{minWidth: "1140px"}}>
                    <div className="modal-content">
                        <div className="modal-header">
                            <h1 className="modal-user__title">Карточка сотрудника</h1>
                            <button type="button" className="btn-close" onClick={handleUserModalCloseButtonClick}
                                    aria-label="Close"></button>
                        </div>
                        <div className="modal-body">
                            {isUserLoading
                                ? <div style={{height: "385px"}}><SpinnerCustom/></div>
                                : <FormUser userAction={userAction}
                                            userData={userData}
                                            initialUserData={initialUserData}
                                            setterUserDataTemp={setterUserDataTemp}
                                            handleAlertOpen={handleAlertOpen}
                                            handleDeleteUser={handleDeleteUser}
                                            submit={submit}
                                            deleteUser={deleteUser}
                                            isUserDataChanged={isUserDataChanged}
                                />
                            }

                        </div>
                    </div>
                </div>
            </div>

            {isApplyModalActive &&
                <ModalApply applyModalTitle={applyModalTitle}
                            applyModalText={applyModalText}
                            applyButtonText={userAction === "delete" ? "Подтвердить" : "Сохранить"}
                            cancelButtonText={userAction === "delete" ? "Отмена" : "Не сохранять"}
                            handleApply={userAction === "delete" ? deleteUser : submit}
                            handleCancel={userAction === "delete"
                                ? () => {
                                }
                                : () => onClose(false)}

                />
            }

        </>
    );
}

export default ModalUser;