import {NavigateFunction} from "react-router-dom";

import {FLOOR_LINK, KEY_CURRENT_LEVEL, KEY_CURRENT_MKD} from "../config/config";
import {regexOnlyNumbers} from "../config/regex";
import {MkdItemType} from "../types/mkd-items.type";

function levelDoubleClickHandler(event: any, mkdItems: MkdItemType[], navigate: NavigateFunction) {
    console.log(event.currentTarget.id);
    const currentLevel: string = event.currentTarget.id.split("-")[event.currentTarget.id.split("-").length - 1];
    currentLevel && localStorage.setItem(KEY_CURRENT_LEVEL, JSON.stringify(currentLevel));

    const mkdId = event.target.parentElement.parentElement.id.replace(regexOnlyNumbers, "");
    let currentItem: MkdItemType | undefined = mkdItems.find((item: MkdItemType) => item.id === mkdId);

    currentItem && localStorage.setItem(KEY_CURRENT_MKD, JSON.stringify(currentItem));

    navigate(FLOOR_LINK);
}

export default levelDoubleClickHandler;