import {useEffect, useState} from "react";

import {Popover} from "bootstrap";

import HeaderMenuItem from "../../components/HeaderMenuItem/HeaderMenuItem";

import {AUTH_LINK, FLOOR_LINK, MKD_LINK, MONITORING_LINK} from "../../../shared/config/config";
import {headerMenuItems} from "../../../shared/config/header-menu-items";

import bellIcon from "../../../assets/images/icons/header-menu/bell.svg";
import logOutIcon from "../../../assets/images/icons/header-menu/log-out.svg";

import {AccountType} from "../../../shared/types/account.type";

import "./Header.scss"


function Header({accountInfo, pathName, onLogout}: {
    accountInfo: AccountType,
    pathName: string,
    onLogout: () => void
}) {
    const [date, setDate] = useState<number>(0);
    const [month, setMonth] = useState<string>("");
    const [hours, setHours] = useState<string>("");
    const [minutes, setMinutes] = useState<string>("/");
    const [linkCurrent, setLinkCurrent] = useState<string>("");
    const [headerMenuItemsImages, setHeaderMenuItemsImages]
        = useState<{ [k: string]: string }>({});

    function getDate(): void {
        const currentDate: Date = new Date();
        setDate(currentDate.getDate());
        setMonth(currentDate.toLocaleString("ru", {month: 'short'}));
        setHours(currentDate.getHours().toString().padStart(2, "0"));
        setMinutes(currentDate.getMinutes().toString().padStart(2, "0"));
    }

    setInterval((): void => {
        getDate();
    }, 1000);

    useEffect((): void => {
        getDate();
    }, [date, month, hours, minutes]);

    useEffect((): void => {
        setLinkCurrent(pathName);
    }, [pathName]);

    useEffect((): void => {
        setHeaderMenuItemsImages(Object.fromEntries(headerMenuItems.map(item => [item.name, item.icon])));
    }, []);

    function handlePopoverShown(): void {
        const logoutButtonElements = document.querySelectorAll(".log-out-link");
        for (let i: number = 0; i < logoutButtonElements.length; i++) {
            logoutButtonElements[i].addEventListener("click", function () {
                onLogout();
            });
        }
    }

    useEffect(() => {
        const popoverElement: HTMLElement | null = document.getElementById('popover-log-out');

        if (popoverElement) {
            popoverElement && new Popover(popoverElement, {
                sanitize: false,
                trigger: 'focus',
                container: 'body',
                placement: 'bottom',
                html: true,
                content: function () {
                    return document.getElementById('popover-content')?.innerHTML;
                }
            });

            popoverElement.addEventListener('shown.bs.popover', handlePopoverShown);
            return (() => popoverElement.removeEventListener('shown.bs.popover', handlePopoverShown))
        }
    }, [pathName]);

    return (
        <header className="header">
            <div className="header__side_left">
                <div className="header__logo">
                    <div className="header__date"><span>{hours}:{minutes}</span>{date}&nbsp;{month}</div>
                </div>

                <nav className="header__menu">
                    <ul>
                        {headerMenuItems.map((item, index: number) => (
                            <HeaderMenuItem
                                key={index}
                                linkCurrent={linkCurrent}
                                setLinkCurrent={setLinkCurrent}
                                isLinkActive={linkCurrent === item.link
                                    || ((linkCurrent === MKD_LINK || linkCurrent === FLOOR_LINK) && item.link === MONITORING_LINK)}
                                link={item.link}
                                nameLink={item.name}
                                iconSrc={headerMenuItemsImages[item.name]}/>
                        ))}
                    </ul>
                </nav>
            </div>
            <div className="header__side_right">
                {/*<div className="header__date"><span>{hours}:{minutes}</span>{date}&nbsp;{month}</div>*/}

                {pathName !== AUTH_LINK &&
                    <>
                        <button type="button">
                            <img
                                src={bellIcon}
                                alt="Иконка уведомлений"
                            />
                        </button>

                        <button id="popover-log-out"
                                tabIndex={-1}
                                type="button"
                                className="btn btn-secondary"
                                data-bs-toggle="popover">
                            <img src={logOutIcon} alt="Иконка выхода из системы"/>
                        </button>

                        <div className="pop-in p-0" id="popover-content" style={{display: "none"}}>
                            {<p className="mb-0 text-center fs-6">{accountInfo.login}</p>}
                            <button className="log-out-link">Выйти из системы</button>
                        </div>
                    </>
                }
            </div>
        </header>
    );
}

export default Header;