import "./WebCamImage.scss";

function WebCamImage({photoWidth}: {photoWidth: number}) {
    let width = photoWidth;    // Этим создадим ширину фотографии
    let height = 0;    // Это будет вычисляться на основе входящего потока

    let streaming = false;

    let video: any = null;
    let canvas: any = null;
    let photo: any = null;

    function startup() {
        video = document.getElementById('video');
        canvas = document.getElementById('canvas');
        photo = document.getElementById('photo');

        if (video) {
            navigator.mediaDevices.getUserMedia({ audio: false, video: {sampleSize: 10} })
                .then((stream) => {
                    video.srcObject = stream;
                })
                .catch(function (err) {
                    console.error("An error occurred: " + err);
                });

            video.addEventListener('canplay', function (ev: any) {
                if (!streaming) {
                    height = video.videoHeight / (video.videoWidth / width);

                    video.setAttribute('width', width);
                    video.setAttribute('height', height);
                    canvas && canvas.setAttribute('width', width);
                    canvas && canvas.setAttribute('height', height);
                    streaming = true;
                }
            }, false);

            clearphoto();
        }
    }

    function onStartButtonClick(ev: any) {
        takepicture();
        ev.preventDefault();
    }

    function clearphoto() {
        if (canvas) {
            let context = canvas.getContext('2d');

            context.fillStyle = "#AAA";
            context.fillRect(0, 0, canvas.width, canvas.height);

            let data = canvas.toDataURL('image/png');

            photo.setAttribute('src', data);
        }
    }

    function takepicture() {
        if (canvas) {
            let context = canvas.getContext('2d');
            if (width && height) {
                canvas.width = width;
                canvas.height = height;

                context.clearRect(0, 0, canvas.width, canvas.height);
                context.save();
                context.scale(-1, 1);
                context.drawImage(video, width * -1, 0, width, height);
                context.restore();

                let data = canvas.toDataURL('image/png');
                photo.setAttribute('src', data);
            } else {
                clearphoto();
            }
        }
    }

    setTimeout(() => {
        startup();
    }, 500);

    return (
        <div>
            <div className="camera">
                <video id="video" autoPlay></video>
                <button className="btn btn-primary" id="start-button" onClick={onStartButtonClick}>Сделать фото</button>
            </div>

            <canvas id="canvas">
            </canvas>

            <div className="output w-100 text-end">
                <img id="photo" alt="Здесь будет фото"/>
            </div>
        </div>
    );
}

export default WebCamImage;