import {createRef, Dispatch, RefObject, SetStateAction, useState} from "react";

import "./FormAuth.scss";

function FormAuth({formType, setFormType, isLoading, onSubmit}: {
    formType: "signup" | "login",
    setFormType: Dispatch<SetStateAction<"signup" | "login">>
    isLoading: boolean,
    onSubmit: (login: string, password: string) => void
}) {
    const formRef: RefObject<HTMLFormElement> = createRef();

    const [isPasswordVisible, setPasswordVisible] = useState<boolean>(false);
    const [isPasswordConfirmVisible, setPasswordConfirmVisible] = useState<boolean>(false);
    const [isButtonDisabled, setButtonDisabled] = useState<boolean>(true);
    const [login, setLogin] = useState<string>("");
    const [password, setPassword] = useState<string>("");

    function togglePasswordVisibility(): void {
        setPasswordVisible(!isPasswordVisible);
    }
    function togglePasswordConfirmVisibility(): void {
        setPasswordConfirmVisible(!isPasswordConfirmVisible);
    }

    function handleInputChange(event: any): void {
        event.target.name === "login"
            ? setLogin(event.target.value)
            : setPassword(event.target.value);

        let isFormValid: boolean = false;

        if (event.target.checkValidity()) {
            if (event.target.name === "password-confirm") {
                const passwordInputElement: HTMLElement | null = document.getElementById("input-password");

                if (passwordInputElement) {
                    if (event.target.value === (passwordInputElement as HTMLInputElement).value) {
                        event.target.classList.remove("form-control_error");
                        isFormValid = true;
                    } else {
                        event.target.classList.add("form-control_error");
                        isFormValid = false;
                    }
                }
            } else {
                event.target.classList.remove("form-control_error");
                isFormValid = true;
            }
        } else {
            event.target.classList.add("form-control_error");
            isFormValid = false;
        }

        if (formRef.current?.checkValidity() && isFormValid) {
            setButtonDisabled(false);
        } else {
            setButtonDisabled(true);
        }
    }

    function handleActionButtonClick() {
        formType === "signup" ? setFormType("login") : setFormType("signup");
    }

    function handleSubmit(event: any): void {
        event.preventDefault();

        if (formRef.current?.checkValidity()) {
            onSubmit(login, password);
        }
    }

    return (
        <form className="auth-form needs-validation" ref={formRef} onSubmit={handleSubmit} noValidate>
            <div className="auth-form__title mb-2">
                {formType === "login" ? "Вход в систему" : "Регистрация"}
            </div>

            <div className="auth-form__item mb-3">
                <label htmlFor="input-login" className="form-label form-label_login w-100">Логин:
                    <input type="text"
                           className="form-control"
                           id="input-login"
                           name="login"
                           placeholder="Введите логин"
                           onChange={handleInputChange}
                           disabled={isLoading}
                           required
                           pattern="(?=.*[A-Za-z\d])(?=.*[A-Za-z])[0-9a-zA-Z]{5,}"
                           title="Логин должен быть длиной не менее 5 символов и содержать большие, маленькие латинские буквы или цифры"
                    />
                </label>
            </div>

            <div className="auth-form__item mb-3">
                <label htmlFor="input-password" className="form-label form-label_password w-100">Пароль:
                    <input type={`${isPasswordVisible ? 'text' : 'password'}`}
                           className="form-control"
                           id="input-password"
                           name="password"
                           placeholder="Введите пароль"
                           disabled={isLoading}
                           onChange={handleInputChange}
                           required
                           pattern="(?=.*\d)(?=.*[@$!%*?&_=+\-])(?=.*[a-z])(?=.*[A-Z])[0-9a-zA-Z@$!%*?&_=+\-]{8,}"
                           title="Пароль должен быть длиной не менее 8 символов и содержать большие и маленькие латинские буквы, цифры, спецсимволы @$!%*?&_=+-"
                    />
                </label>

                <button type="button"
                        className={`password-visibility-button ${isPasswordVisible ? 'password-visibility-button_visible' : ''}`}
                        onClick={togglePasswordVisibility}>
                </button>
            </div>

            {formType === "signup" &&
                <div className="auth-form__item mb-3">
                    <label htmlFor="input-password-confirm" className="form-label form-label_password w-100">Подтверждение
                        пароля:
                        <input type={`${isPasswordConfirmVisible ? 'text' : 'password'}`}
                               className="form-control"
                               id="input-password-confirm"
                               name="password-confirm"
                               placeholder="Подтвердите пароль"
                               disabled={isLoading}
                               onChange={handleInputChange}
                               required
                               pattern="(?=.*\d)(?=.*[@$!%*?&_=+\-])(?=.*[a-z])(?=.*[A-Z])[0-9a-zA-Z@$!%*?&_=+\-]{8,}"
                               title="Пароль должен быть длиной не менее 8 символов и содержать большие и маленькие латинские буквы, цифры, спецсимволы @$!%*?&_=+-"
                        />
                    </label>

                    <button type="button"
                            className={`password-visibility-button ${isPasswordConfirmVisible ? 'password-visibility-button_visible' : ''}`}
                            onClick={togglePasswordConfirmVisibility}>
                    </button>
                </div>
            }

            <button type="submit" className="btn btn-primary submit-button" disabled={isLoading || isButtonDisabled}>
                {formType === "login" ? "Войти" : "Зарегистрироваться"}
            </button>

            <button type="button" className="action-button" disabled={isLoading} onClick={handleActionButtonClick}>
                {formType === "login" ? "Зарегистрироваться" : "Войти"}
            </button>

        </form>
    );
}

export default FormAuth;